export interface QuizQuestion {
  question: string
  options: string[]
  answer: number
  explanation: string
}

export interface Lesson {
  id: string
  title: string
  duration: number
  intro: string
  sections: { heading: string; body: string; points: string[] }[]
  keyPoints: string[]
  activity: { title: string; purpose: string; steps: string[]; deliverable: string }
  reflection: string
  quiz: QuizQuestion
}

export interface CourseModule {
  id: string
  number: string
  title: string
  shortTitle: string
  category: string
  icon: string
  level: string
  summary: string
  outcomes: string[]
  hours: number
  lessons: Lesson[]
}

const lessonApplications: Record<string, { body: string; points: string[] }> = {
  'meaning-of-yoga': { body: 'Al presentar el yoga a un grupo, explicita desde qué tradición, autor o experiencia estás hablando. Una definición puede servir como puerta de entrada, pero no como veredicto que invalide otras prácticas. La precisión cultural también consiste en decir “no lo sé” y orientar hacia una fuente fiable.', points: ['Distingue una descripción histórica de tu interpretación personal.', 'Evita presentar la práctica contemporánea como una tradición única e inmutable.', 'Usa fuentes identificables cuando hagas afirmaciones históricas.'] },
  'eight-limbs': { body: 'El esquema de Patañjali puede abrir una conversación sobre cómo se relacionan la conducta, la práctica corporal, la respiración y la atención. No hace falta convertirlo en una secuencia obligatoria ni puntuar la vida ética del alumnado: el objetivo es estudiar el modelo y explorar sus lecturas.', points: ['Nombra los ocho miembros en su contexto textual.', 'Diferencia una lectura tradicional de una adaptación pedagógica actual.', 'Invita a reflexionar sin imponer una creencia ni jerarquizar personas.'] },
  'yamas-niyamas': { body: 'Los principios éticos se comprueban en decisiones observables: cómo respondes a una negativa, cómo corriges una frase dañina o qué haces ante una asimetría de poder. Trabaja con casos concretos y más de una respuesta posible; la ética profesional exige analizar consecuencias y límites, no etiquetar a alguien como “bueno” o “malo”.', points: ['Formula el dilema y las personas afectadas antes de proponer una respuesta.', 'Identifica cómo proteger autonomía, dignidad y seguridad.', 'Revisa la decisión después de escuchar al grupo y su contexto.'] },
  'yoga-sutras': { body: 'Para estudiar un aforismo, registra el texto, la edición, el traductor y el comentario consultado. Compara qué matices aparecen o desaparecen en cada versión y separa el sentido que propone una escuela de la interpretación que haces tú. Esa práctica evita convertir citas breves en eslóganes sin contexto.', points: ['Conserva la referencia exacta de la traducción utilizada.', 'Señala los términos cuya interpretación cambia entre fuentes.', 'No derives recomendaciones médicas de una lectura filosófica.'] },
  'philosophy-in-class': { body: 'Una idea filosófica puede traducirse en una invitación breve —observar, escuchar o elegir— sin pedir al alumnado que comparta una visión espiritual. Presenta la intención como una opción y permite que cada persona la interprete, la adapte o sencillamente practique en silencio.', points: ['Usa lenguaje invitacional, no prescriptivo.', 'Incluye una alternativa secular o silenciosa cuando corresponda.', 'No prometas que una idea filosófica eliminará sufrimiento o síntomas.'] },
  'early-sources': { body: 'Las referencias védicas y las Upanishads pertenecen a corpus diversos que se formaron en periodos distintos y no constituyen un manual uniforme de yoga postural. Al enseñar su contexto, diferencia género textual, antigüedad aproximada y tradiciones interpretativas; evita utilizar una única cita como prueba de una afirmación amplia.', points: ['Identifica qué texto estás citando y en qué traducción.', 'Distingue ritual, reflexión filosófica y sistemas posteriores.', 'Reconoce lagunas o desacuerdos en las reconstrucciones históricas.'] },
  'bhagavad-gita': { body: 'La Bhagavad Gītā presenta una conversación filosófica y religiosa situada dentro del Mahābhārata. Sus ideas sobre acción, conocimiento, devoción y disciplina han recibido lecturas variadas; explica de qué interpretación procede tu explicación y evita reducir sus caminos a una receta motivacional desligada del texto.', points: ['Contextualiza el diálogo, sus personajes y el problema que aborda.', 'Compara interpretaciones sin tratarlas como idénticas.', 'No uses el texto para justificar que una persona soporte daño o abuso.'] },
  'hatha-history': { body: 'La historia del haṭha yoga, las prácticas corporales modernas y el yoga postural contemporáneo incluye continuidades, cambios e intercambios. Al explicar una postura o una secuencia, evita tanto afirmar que todo es ancestral como descartar tradiciones complejas con una sola fecha: define el periodo y la fuente de cada afirmación.', points: ['Separa el haṭha yoga premoderno de estilos posturales recientes.', 'Reconoce influencias culturales e históricas múltiples.', 'Distingue documentación histórica de relatos comerciales de origen.'] },
  'lineages': { body: 'Los nombres de los estilos pueden describir linaje, metodología, ritmo o énfasis, pero no garantizan que todas las clases con la misma etiqueta sean iguales. Para comparar enfoques, describe prácticas concretas y pregunta qué experiencia ofrecen, para quién y con qué condiciones de participación.', points: ['Describe método y contexto antes de asignar una etiqueta.', 'No conviertas una preferencia personal en una clasificación universal.', 'Comprueba formación y alcance docente, no solo el nombre del estilo.'] },
  'cultural-responsibility': { body: 'La responsabilidad cultural se practica citando las fuentes, evitando exotizar símbolos y reconociendo cuándo una enseñanza procede de una tradición religiosa viva. Si no conoces el origen de un canto, símbolo o término, investígalo antes de incluirlo y ofrece al alumnado información y elección sin convertir la cultura en decoración.', points: ['Cita personas, textos o comunidades cuando sea posible.', 'Evita afirmar que una práctica pertenece a “toda la India” o a todo el yoga.', 'Corrige errores con transparencia y sin apropiarte de autoridad que no tienes.'] },
  'movement-language': { body: 'Los planos y ejes sirven para describir movimientos, no para clasificar un cuerpo como correcto o incorrecto. Practica nombrando la acción y la dirección respecto al propio cuerpo de la persona; después comprueba si tu indicación se entiende y si resulta útil para la tarea propuesta.', points: ['Usa términos anatómicos consistentes y comprensibles.', 'Distingue movimiento relativo, posición inicial y orientación espacial.', 'Evita inferir una lesión o una disfunción solo a partir de una observación visual.'] },
  'spine-core': { body: 'La columna tiene curvas y grados de movilidad que varían entre personas. En la práctica, interesa repartir el movimiento, respirar y ajustar la intensidad a la respuesta individual; no existe una única postura “neutral” que deba imponerse a todos los cuerpos en cualquier contexto.', points: ['Observa comodidad, control y respiración, no solo una forma ideal.', 'Modifica palancas, apoyo o rango antes de pedir más amplitud.', 'Ante dolor persistente, síntomas neurológicos o preocupación clínica, deriva a personal sanitario.'] },
  'hip-anatomy': { body: 'La forma articular, las proporciones y el tejido varían, por lo que dos estudiantes pueden sentir distinta amplitud aun utilizando una estrategia razonable. Enseña opciones de base, distancia y apoyo; no empujes a nadie a superar una sensación de bloqueo ni prometas “abrir” una estructura anatómica.', points: ['Ofrece más de una posición de piernas y pelvis.', 'Pregunta por la sensación de la persona en lugar de adivinarla.', 'Diferencia tensión, esfuerzo tolerable, dolor y señales para detenerse.'] },
  'shoulder-wrist': { body: 'En apoyos de manos, la carga depende del ángulo articular, la fuerza, el tiempo y la superficie. La solución pedagógica no consiste siempre en “alinear” más, sino en cambiar altura, distribución de peso o tarea, y comprobar si la persona puede entrar y salir con control.', points: ['Prueba pared, bloques, puños u otra posición cuando sea apropiado.', 'Aumenta la carga de forma gradual, no por presión del grupo.', 'No diagnostiques un problema de hombro o muñeca desde la esterilla.'] },
  'muscle-tendon-load': { body: 'La tolerancia a la carga se desarrolla con dosis, descanso y adaptación. Una postura mantenida no es automáticamente mejor que una repetición dinámica, y la intensidad percibida no debe usarse como competición. Planifica progresión y recuperación a lo largo de semanas, no solo dentro de una clase.', points: ['Incrementa una variable cada vez: tiempo, rango, complejidad o carga.', 'Observa la respuesta durante la práctica y después de ella.', 'Programa alternativas de menor demanda sin presentarlas como un fracaso.'] },
  'standing-poses': { body: 'En las posturas de pie, la base, la orientación de los pies y la distribución de carga cambian la estrategia disponible. Ofrece un punto de partida y deja que cada persona ajuste la distancia de las piernas, el apoyo de la pared o la duración en función de equilibrio y comodidad.', points: ['Comprueba espacio libre y estabilidad antes de iniciar.', 'Evita forzar la rodilla o el pie a un ángulo estándar para todos.', 'Enfatiza salir de la postura de forma controlada y sin prisa.'] },
  'forward-folds': { body: 'Una flexión combina movimiento de cadera, columna, rodillas y estrategia de apoyo. La versión apropiada puede tener rodillas flexionadas, manos en bloques o el tronco más elevado; “llegar al suelo” no es un criterio de aprendizaje ni una medida fiable de salud.', points: ['Reduce la palanca con apoyos y flexión de rodillas si conviene.', 'Enseña a entrar y salir sin rebotes ni tracción externa.', 'Respeta síntomas agudos o irradiados y suspende ante señales de alarma.'] },
  'backbends': { body: 'En una extensión, el objetivo no es maximizar la curvatura lumbar. La distribución del movimiento depende de la tarea, las proporciones y la experiencia, así que puede ser útil reducir rango, elevar las manos, apoyar la pelvis o practicar una extensión más baja.', points: ['Prepara apoyos y una salida clara antes de profundizar.', 'Evita empujar físicamente el cuerpo para aumentar la extensión.', 'Observa respiración, control y respuesta posterior, no solo la altura alcanzada.'] },
  'twists': { body: 'Las torsiones se pueden explorar con diferentes apoyos, alturas y grados de giro; no hace falta llevar hombros y pelvis a una figura idéntica en cada persona. Prioriza control, respiración cómoda y ausencia de presión externa, y adapta la propuesta en embarazo u otras circunstancias según formación específica y orientación sanitaria pertinente.', points: ['Usa una progresión suave y permite reducir el rango.', 'No utilices los brazos como palanca para forzar el giro.', 'Si una condición requiere modificación clínica, consulta a profesionales competentes.'] },
  'balances-inversions': { body: 'El equilibrio y las inversiones requieren valorar experiencia, superficie, espacio, fatiga y posibilidad de salir de la posición. Una pared, una variante baja o una práctica sin inversión pueden ser objetivos válidos; no conviertas la dificultad o el riesgo en una demostración de mérito.', points: ['Establece cómo entrar, sostener y salir antes de probar.', 'No introduzcas inversiones bajo presión ni en espacios congestionados.', 'Ofrece una alternativa equivalente que mantenga el objetivo de la clase.'] },
  'observe-first': { body: 'La observación docente funciona mejor como una hipótesis provisional: describe lo visible, pregunta por la experiencia y decide si hace falta intervenir. La apariencia no revela automáticamente dolor, intención, estado emocional ni diagnóstico; en ocasiones, la opción más responsable es no corregir.', points: ['Separa datos visibles de interpretaciones.', 'Observa a todo el grupo y no fijes la atención siempre en la misma persona.', 'Antes de ajustar, pregúntate si el cambio es necesario para el objetivo.'] },
  'props': { body: 'Los accesorios modifican distancia, altura, superficie y estabilidad; no son premios ni remedios universales. Demuestra cómo colocar cada material con seguridad, comprueba que no resbale y enseña a elegir el apoyo sin exponer a nadie a explicar públicamente por qué lo necesita.', points: ['Inspecciona el material y deja rutas de paso despejadas.', 'Explica que las opciones se eligen por función, no por nivel social.', 'Adapta la propuesta si un accesorio aumenta la molestia o inestabilidad.'] },
  'verbal-cues': { body: 'Una indicación útil destaca una acción cada vez y deja tiempo para que la persona la procese. Prueba secuencias de verbo, referencia espacial y criterio sensorial: por ejemplo, “apoya ambos pies; alarga el tronco; mantén una respiración cómoda”. Después observa si la instrucción produce el efecto buscado.', points: ['Prioriza una indicación esencial frente a una cadena larga.', 'Evita comentarios estéticos y absolutos sobre el cuerpo.', 'Usa pausas para que el alumnado pueda sentir y decidir.'] },
  'individual-variation': { body: 'Una adaptación mantiene el propósito del ejercicio mientras cambia la forma, el rango, la carga o el apoyo. La alternativa no tiene por qué parecerse visualmente a la postura original; debe ser comprensible, segura en contexto y elegida con la participación del estudiante.', points: ['Define el objetivo antes de buscar una variante.', 'Ofrece opciones sin exigir que la persona revele información médica.', 'Reevalúa si la modificación facilita realmente la tarea.'] },
  'pain-and-stop': { body: 'El profesor no necesita averiguar la causa de un dolor para responder con cuidado: detener, salir de la posición y escuchar es distinto de diagnosticar. No presiones para “respirar a través” de dolor agudo, mareo, entumecimiento, falta de aire inusual u otros síntomas preocupantes.', points: ['Deja claro que cualquier persona puede pausar sin justificarlo.', 'No minimices síntomas ni interpretes el dolor como resistencia mental.', 'Deriva a atención sanitaria cuando proceda y activa emergencias ante signos graves.'] },
  'breathing-basics': { body: 'La ventilación es un proceso fisiológico automático que también puede modificarse voluntariamente. Explica la coordinación respiratoria sin exigir un patrón perfecto: la postura, el esfuerzo, el estado emocional y las diferencias individuales pueden cambiar la experiencia, y una respiración cómoda tiene prioridad sobre la estética de la técnica.', points: ['No fuerces inhalaciones profundas ni vaciados completos.', 'Permite volver a la respiración espontánea en cualquier momento.', 'No equipares automáticamente una respiración visible con un problema.'] },
  'breath-awareness': { body: 'Invitar a notar el aire puede resultar útil, neutro o incómodo según la persona y el momento. Ofrece focos alternativos —contacto de los pies, sonidos externos o mirada suave— y evita sugerir que una experiencia interna concreta sea obligatoria para participar correctamente.', points: ['Presenta la atención a la respiración como opción, no como examen.', 'Permite abrir los ojos, moverse o cambiar de anclaje.', 'Pregunta por comodidad en lugar de interpretar emociones ajenas.'] },
  'ujjayi': { body: 'Ujjayi suele describirse por una constricción suave en la zona de la glotis que produce un sonido discreto, pero la instrucción puede acabar en tensión si se exagera. Enseña primero una respiración natural y deja que el alumnado abandone el sonido en cuanto aparezcan esfuerzo, sequedad o ansiedad.', points: ['No empujes el volumen ni impongas el mismo patrón a todos.', 'Evita retenciones implícitas si no forman parte de una enseñanza competente.', 'Compara la comodidad con y sin técnica antes de continuar.'] },
  'alternate-nostril': { body: 'La respiración alterna requiere coordinación de dedos, atención y un flujo cómodo; la técnica no debería generar competencia ni sensación de falta de aire. Enseña primero la secuencia sin retenciones y ofrece una práctica respiratoria natural para cualquier estudiante que prefiera no participar.', points: ['Explica el patrón antes de empezar y practica lentamente.', 'No obstruyas la nariz con presión excesiva ni fuerces la inhalación.', 'Interrumpe la técnica si aparecen mareo, angustia o dificultad respiratoria.'] },
  'breath-retention': { body: 'Las retenciones y las prácticas respiratorias intensas no son necesarias para demostrar competencia docente y pueden causar síntomas en algunas personas. Para un grupo general, prioriza opciones suaves, consentimiento explícito y criterio de exclusión prudente; no enseñes técnicas exigentes sin formación específica y evaluación adecuada del contexto.', points: ['No compitas por duración ni premies aguantar síntomas.', 'Evita la hiperventilación deliberada en contextos inseguros o sin supervisión competente.', 'Ante mareo, hormigueo intenso o angustia, vuelve a respirar con normalidad y detén la técnica.'] },
  'attention-basics': { body: 'La atención fluctúa y puede dirigirse a estímulos internos o externos; distraerse no es un fallo moral. Una guía eficaz invita a notar que la atención se ha ido y regresar sin reprimenda, con periodos breves y un objeto de atención elegido por el participante.', points: ['Define un anclaje simple y opcional.', 'Normaliza que aparezcan pensamientos o sonidos.', 'Mide la práctica por la oportunidad de regresar, no por la ausencia de distracción.'] },
  'guided-meditation': { body: 'Una meditación breve necesita una estructura comprensible: orientación, invitación, tiempo de silencio y cierre gradual. Habla menos de lo que crees necesario, permite que los ojos permanezcan abiertos y no pidas revelar experiencias personales al terminar.', points: ['Anuncia duración y opciones de postura con antelación.', 'Deja silencios suficientes sin llenar cada segundo con palabras.', 'Cierra reorientando al espacio y ofrece participación verbal opcional.'] },
  'restorative-savasana': { body: 'El descanso final es una práctica y no una prueba de quietud. Deja que el alumnado elija estar tumbado, de lado, sentado o con ojos abiertos; organiza mantas y soportes sin contacto no solicitado y ofrece una salida lenta para volver a moverse.', points: ['Explica alternativas antes de que todo el grupo se tumbe.', 'No interpretes movimiento, ojos abiertos o salida anticipada como falta de compromiso.', 'Evita tocar para “relajar” sin consentimiento específico.'] },
  'meditation-trauma-aware': { body: 'Una enseñanza sensible a experiencias diversas da previsibilidad, elección y control al participante. La atención al cuerpo o a la respiración puede no ser cómoda para todo el mundo; se pueden ofrecer anclajes externos, movimiento suave, ojos abiertos o descanso, sin pedir que alguien explique su historia.', points: ['Describe lo que sucederá antes de guiarlo.', 'Usa invitaciones reversibles y alternativas visibles.', 'No prometas tratar trauma ni sustituyas apoyo psicológico especializado.'] },
  'teach-silence': { body: 'El silencio puede dar espacio para integrar, pero también puede dejar al grupo sin orientación si no se prepara. Indica dónde termina la práctica, cuánto durará el cierre cuando sea útil y cómo salir; después, permite que cada persona decida si quiere hablar.', points: ['Usa el silencio con una intención docente clara.', 'Ofrece señales de transición previsibles y suaves.', 'No fuerces una ronda de emociones o testimonios.'] },
  'sanskrit-principles': { body: 'La transliteración académica usa marcas que distinguen sonidos y vocales; la pronunciación varía según lengua y tradición oral. Para enseñar un término, muestra la escritura elegida, aporta una guía simple y reconoce los límites de tu pronunciación en vez de fingir autoridad lingüística.', points: ['Conserva diacríticos en material escrito cuando estén disponibles.', 'Comprueba pronunciación con fuentes o docentes cualificados.', 'No ridiculices acentos ni conviertas la pronunciación en una prueba de pertenencia.'] },
  'asana-etymology': { body: 'Los nombres de asanas pueden incluir términos descriptivos, referencias a animales, figuras, sabios o conceptos y sus significados pueden tener historias complejas. La etimología ayuda a recordar el nombre, pero no garantiza que una postura moderna reproduzca una figura antigua o que exista una única explicación aceptada.', points: ['Desglosa el término solo cuando la fuente lo permita.', 'Separa etimología, leyenda y explicación contemporánea.', 'Si hay varias versiones, indícalo en vez de presentar una como certeza.'] },
  'sanskrit-name-anatomy': { body: 'Reconocer componentes como adho, ūrdhva, eka, pāda, mukha o hasta puede ayudar a descifrar nombres, pero las combinaciones tienen reglas y contexto. Usa ejemplos contrastados y evita traducir palabra por palabra cuando el uso tradicional o la forma del compuesto necesiten explicación adicional.', points: ['Construye un glosario con término, transliteración y fuente.', 'Señala variaciones ortográficas y de pronunciación.', 'No inventes la traducción de un nombre por intuición visual.'] },
  'mantra-context': { body: 'Antes de invitar a cantar, explica de forma proporcionada el origen que conoces, el sentido atribuido y cómo se participará. Escuchar en silencio o no participar debe ser posible sin llamar la atención sobre esa decisión; la repetición sonora no debe presentarse como tratamiento médico garantizado.', points: ['Verifica texto, pronunciación y contexto antes de guiarlo.', 'Permite cantar, escuchar o permanecer en silencio.', 'No generalices el significado de una práctica religiosa entre comunidades.'] },
  'mudras-symbols': { body: 'Un gesto manual puede tener interpretaciones distintas entre textos, linajes y contextos de práctica. Si se usa como símbolo, explica de dónde procede esa lectura; si se usa como apoyo de atención, descríbelo así. La mano debe poder descansar en otra posición cómoda sin perder el hilo de la clase.', points: ['Diferencia relato tradicional de evidencia fisiológica.', 'No prometas efectos energéticos o terapéuticos como hechos demostrados.', 'Incluye una alternativa neutra si el gesto molesta o no interesa.'] },
  'class-arc': { body: 'La estructura de una clase debe servir a un objetivo alcanzable y a las condiciones del grupo, no a una fórmula inamovible. Planifica llegada, preparación, desarrollo, descenso de intensidad y cierre, y reserva tiempo para transiciones, instrucciones, preguntas y opciones que puedan surgir.', points: ['Asigna minutos realistas a cada bloque, incluida la entrada y salida.', 'Comienza con una carga coherente con experiencia y contexto.', 'Deja margen para adaptar el plan sin perder el objetivo principal.'] },
  'peak-pose': { body: 'Una postura central no necesita ser extrema; puede elegirse por el patrón de movimiento o por una habilidad que se desea explorar. La progresión prepara componentes relevantes, permite omitir etapas y ofrece una alternativa que conserve la intención sin exigir el mismo resultado a todo el grupo.', points: ['Identifica demandas relevantes antes de diseñar la progresión.', 'Introduce calentamiento y preparación relacionados, no solo genéricos.', 'Incluye una opción de salida y un modo más sencillo de participar.'] },
  'transitions': { body: 'Una secuencia segura describe tanto la llegada como la salida: dónde va el peso, qué apoyo se mantiene, qué extremidad se mueve primero y cómo se orienta el cuerpo. El profesor debe prever dónde puede haber tropiezos, choques o cambios bruscos de carga y ajustar el ritmo para que nadie tenga que improvisar bajo presión.', points: ['Escribe cada transición como acciones observables y ordenadas.', 'Comprueba apoyos, espacio disponible y dirección de desplazamiento.', 'Practica la transición lentamente antes de añadir velocidad o fluidez.'] },
  'breath-and-flow': { body: 'Coordinar movimiento y respiración puede crear ritmo, pero el gesto no debe acelerarse para seguir un conteo que no resulta cómodo. Permite respirar a un ritmo individual, detener el flujo o dividir una transición en pasos cuando una instrucción simultánea resulta demasiado exigente.', points: ['Da prioridad a control y orientación espacial sobre sincronía perfecta.', 'Reduce complejidad cuando hablar y moverse a la vez sobrecarga al grupo.', 'Ofrece una pausa entre posturas como alternativa legítima.'] },
  'sequencing-scenarios': { body: 'Una misma secuencia puede necesitar ajustes según experiencia, tamaño del grupo, espacio, equipamiento y propósito. Diseña rutas A y B que compartan la intención, define cómo pasar entre ellas sin señalar niveles públicamente y ensaya cómo reaccionar si varias personas prefieren descansar.', points: ['Especifica objetivo, población, duración y restricciones del escenario.', 'Prepara al menos una alternativa por tramo de mayor demanda.', 'Evalúa la secuencia con criterios observables, no por su apariencia.'] },
  'learning-objectives': { body: 'Un objetivo didáctico puede observarse sin convertir la experiencia subjetiva en una puntuación. Combina una acción, un contexto y un criterio de calidad; después selecciona una evidencia realista, como guiar una transición, justificar una variante o identificar una señal para pausar.', points: ['Usa verbos que describan un desempeño concreto.', 'Alinea actividad y evaluación con el objetivo anunciado.', 'No califiques experiencias internas como serenidad o espiritualidad obligatoria.'] },
  'teach-without-demo': { body: 'Demuestra cuando la referencia visual añade valor y vuelve a una posición que te permita observar. Si practicas todo el bloque frente al grupo, puede que no veas dificultades de espacio, dudas o señales para pausar; alterna demostración, instrucción verbal y exploración supervisada.', points: ['Decide de antemano qué movimientos demostrarás.', 'Colócate donde puedas observar al máximo de participantes.', 'Confirma comprensión y ofrece tiempo de práctica sin hablar continuamente.'] },
  'feedback': { body: 'Un feedback útil describe la acción observada y ofrece una opción que la persona pueda rechazar. La formulación debe ser específica, sin atribuir intenciones ni comparar con otros; pregunta después qué cambió y acepta que mantener la variante inicial también puede ser una decisión informada.', points: ['Describe hechos y conecta la sugerencia con un objetivo.', 'Evita diagnosticar, avergonzar o elogiar solo la forma corporal.', 'Respeta la respuesta del alumno aunque no siga tu indicación.'] },
  'group-management': { body: 'La gestión del espacio comienza antes de que entre el grupo: revisa circulación, accesibilidad, materiales, sonido y posibles salidas. Establece acuerdos breves que protejan la seguridad y la convivencia; cuando haya una interrupción, intervén con calma y de forma proporcional, sin convertirla en un reproche público.', points: ['Mantén accesos, pasillos y material libres de obstáculos.', 'Explica cómo pedir ayuda, descansar o salir de la sala.', 'Comunica límites con claridad y sin humillación.'] },
  'reflective-practice': { body: 'Una revisión útil registra qué se planeó, qué ocurrió y qué cambiarás, sin escribir una historia clínica o personal del alumnado. Escoge una pregunta para la siguiente sesión y prueba una modificación a la vez, de modo que puedas evaluar su efecto sin atribuir cualquier resultado a una sola causa.', points: ['Registra observaciones concretas en lugar de juicios globales.', 'Elimina nombres y datos personales que no sean necesarios.', 'Cierra cada reflexión con una acción pequeña y comprobable.'] },
  'consent-touch': { body: 'Un consentimiento real es informado, específico, voluntario y revocable; la relación profesor-alumno puede crear presión aunque la pregunta parezca cordial. Explica qué harías, espera una respuesta afirmativa y ofrece una alternativa sin contacto. Un “no”, el silencio o un cambio de opinión se respetan sin pedir justificación.', points: ['Pregunta antes de acercarte o tocar.', 'Evita formular la pregunta delante del grupo si puede presionar.', 'El consentimiento no amplía tu competencia ni autoriza manipulaciones inadecuadas.'] },
  'scope-and-referral': { body: 'La función de un profesor de yoga es enseñar prácticas para las que está formado, observar respuestas generales y recomendar apoyo profesional cuando una necesidad excede su competencia. No diagnostiques lesiones, no modifiques tratamientos y no prometas tratar problemas físicos o de salud mental; puedes ayudar a la persona a identificar el tipo de profesional apropiado.', points: ['Explica con honestidad tu formación y sus límites.', 'Deriva con respeto, sin alarmismo ni afirmaciones clínicas.', 'Ante una emergencia, activa el protocolo local en lugar de improvisar tratamiento.'] },
  'inclusive-language': { body: 'Un lenguaje inclusivo nombra opciones y funciones sin asumir edad, género, movilidad, experiencia, peso o capacidad de nadie. En lugar de ordenar una única forma, describe apoyos, alternativas y objetivos; evita usar cuerpos, flexibilidad o dificultad como indicadores de valor o dedicación.', points: ['No presupongas que todo el mundo puede arrodillarse o tumbarse.', 'Ofrece opciones sin convertirlas en una etiqueta de nivel.', 'Pregunta por preferencias de lenguaje cuando sea pertinente.'] },
  'privacy-and-safeguarding': { body: 'Las notas docentes deben limitarse a la información necesaria para impartir una clase segura. Explica cómo se tratarán las comunicaciones y los datos, no compartas imágenes o historias identificables sin autorización adecuada y sigue la normativa aplicable y los protocolos de protección del espacio donde trabajes.', points: ['Recoge el mínimo de información que realmente necesitas.', 'Protege dispositivos, archivos y conversaciones con el alumnado.', 'Consulta los requisitos locales de privacidad y salvaguarda antes de ejercer.'] },
  'emergency-readiness': { body: 'La preparación comienza con un plan conocido: dirección exacta del lugar, acceso para emergencias, teléfono disponible, material de primeros auxilios y roles definidos. El profesor debe mantener la calma, activar servicios de emergencia cuando sea necesario y actuar dentro de su formación; una clase de yoga no sustituye entrenamiento actualizado en primeros auxilios.', points: ['Conoce el procedimiento del centro y cómo pedir ayuda.', 'No muevas innecesariamente a una persona con posible lesión grave.', 'Registra el incidente de forma objetiva siguiendo el protocolo y la privacidad.'] },
  'microteaching': { body: 'Una microenseñanza breve permite probar claridad, ritmo y capacidad de observar, no demostrar una secuencia espectacular. Define un objetivo, guía un tramo corto con opciones y recoge feedback centrado en conductas concretas; después repite el segmento aplicando un cambio que puedas explicar.', points: ['Ensaya con tiempo limitado y un objetivo observable.', 'Solicita feedback sobre instrucciones, seguridad, inclusión y transición.', 'Documenta qué cambiaste y qué evidencia te llevó a hacerlo.'] },
  'assessment-competencies': { body: 'Evaluar docencia requiere más que recordar términos: el estudiante necesita justificar decisiones, guiar un fragmento, ofrecer alternativas y reconocer sus límites. Usa una rúbrica transparente, evidencia observada y oportunidad de mejora; un error inicial debe conducir a feedback y práctica, no a una etiqueta fija.', points: ['Alinea cada criterio con una competencia relevante.', 'Combina observación práctica, explicación y reflexión.', 'No presentes un cuestionario de la app como acreditación profesional.'] },
  'portfolio': { body: 'Un portfolio muestra evolución mediante planes, prácticas, feedback y reflexiones revisadas, no solo una colección de logros. Incluye ejemplos anonimizados, fecha y contexto, explica qué cambió tras recibir comentarios y distingue trabajo propio de material que pertenece a otras personas.', points: ['Selecciona evidencias que demuestren distintas competencias.', 'Añade una reflexión crítica a cada pieza importante.', 'Obtén permiso y elimina datos identificables antes de compartir material.'] },
  'professional-path': { body: 'El desarrollo profesional incluye formación continua, supervisión, comunidad, condiciones de trabajo, comunicación honesta y gestión responsable del negocio. Describe tus servicios y cualificaciones sin promesas terapéuticas ni resultados garantizados, acuerda precios y cancelaciones por adelantado y revisa las obligaciones legales aplicables donde ejerzas.', points: ['Mantén un registro de formación continua y límites de competencia.', 'Comunica credenciales, precios y condiciones con transparencia.', 'Revisa seguros, fiscalidad, protección de datos y normativa de tu jurisdicción con profesionales adecuados.'] },
  'final-capstone': { body: 'El proyecto final integra todas las áreas en una clase enseñable, no en un guion idealizado. Explicita para quién diseñas, por qué eliges cada bloque, qué alternativas ofreces y cómo actuarás ante una dificultad. La revisión de otra persona y un nuevo ensayo son partes centrales del proyecto, no extras opcionales.', points: ['Justifica secuencia, ritmo, lenguaje, opciones y cierre.', 'Incluye una revisión explícita de riesgos, consentimiento y límites.', 'Presenta feedback recibido, cambios realizados y próximos objetivos de aprendizaje.'] },
}

function lesson(
  id: string,
  title: string,
  duration: number,
  intro: string,
  concept: string,
  points: string[],
  activityTitle: string,
  activityPurpose: string,
  steps: string[],
  deliverable: string,
  reflection: string,
  question: string,
  options: string[],
  answer: number,
  explanation: string,
): Lesson {
  return {
    id, title, duration, intro,
    sections: [
      { heading: 'Comprender el concepto', body: concept, points },
      {
        heading: 'Aplicación y criterio docente',
        body: lessonApplications[id]?.body ?? `Lleva el concepto a una situación docente concreta: ${activityPurpose.toLocaleLowerCase('es')}. Antes de decidir, identifica el objetivo, las condiciones del grupo y las opciones disponibles; después observa la respuesta, registra qué evidencia tienes y revisa el plan si no facilita el aprendizaje esperado.`,
        points: lessonApplications[id]?.points ?? [`Punto de partida: ${steps[0]}`, `Siguiente decisión: ${steps[1] ?? 'Revisa el resultado y anota lo aprendido.'}`, `Evidencia: ${deliverable}`],
      },
    ],
    keyPoints: points,
    activity: { title: activityTitle, purpose: activityPurpose, steps, deliverable },
    reflection,
    quiz: { question, options, answer, explanation },
  }
}

export const curriculum: CourseModule[] = [
  {
    id: 'philosophy', number: '01', title: 'Filosofía y fundamentos del yoga', shortTitle: 'Filosofía', category: 'Humanidades del yoga', icon: '◌', level: 'Fundamentos', hours: 18,
    summary: 'Explora qué significa yoga en distintas tradiciones, los Yoga Sutras, los ocho miembros y cómo traducir reflexión filosófica en una práctica ética cotidiana.',
    outcomes: ['Distinguir práctica, filosofía y tradición.', 'Explicar los ocho miembros del yoga sin reducirlos a posturas.', 'Aplicar yamas y niyamas a dilemas reales de enseñanza.'],
    lessons: [
      lesson('meaning-of-yoga','¿Qué llamamos yoga?',12,'Antes de enseñar una técnica, conviene entender el marco al que pertenece y evitar la idea de que existe una única definición válida para toda época y tradición.','La palabra yoga se ha interpretado como unión, disciplina, integración o método contemplativo según el contexto. Las tradiciones clásicas de la India no forman una sola escuela: diferentes textos y linajes proponen metas y métodos distintos. El yoga postural contemporáneo es una parte importante de la historia moderna, pero no agota el significado histórico del término.', ['Yoga tiene una historia plural y cambiante.','La práctica física no representa por sí sola todas las dimensiones del yoga.','Nombra la tradición que estudias y reconoce lo que no sabes.'],'Mapa de significados','Practicar una explicación clara y humilde.', ['Escribe tres asociaciones que haces con la palabra yoga.','Añade una definición centrada en una tradición y otra centrada en tu experiencia.','Señala qué afirmaciones necesitarías verificar antes de enseñarlas.'],'Un mapa personal de conceptos y una definición de 60 segundos.','¿Qué ideas previas sobre el yoga quiero revisar al convertirme en docente?','¿Cuál es la afirmación más rigurosa?',['El yoga siempre ha significado únicamente ejercicio físico.','Todas las tradiciones de yoga enseñan exactamente lo mismo.','El significado y los métodos varían entre textos, épocas y linajes.','La filosofía no tiene relación con la práctica.'],2,'Reconocer la pluralidad histórica evita presentar una versión contemporánea como si fuera la única forma auténtica.'),
      lesson('eight-limbs','Los ocho miembros de Patañjali',16,'El modelo de aṣṭāṅga yoga de los Yoga Sutras organiza una vía de práctica que va mucho más allá de la forma externa de una postura.','Los ocho miembros suelen enumerarse como yama, niyama, āsana, prāṇāyāma, pratyāhāra, dhāraṇā, dhyāna y samādhi. Es útil estudiarlos como un mapa interrelacionado, no como una escalera rígida ni como una lista de requisitos morales para juzgar al alumnado. Las interpretaciones varían entre comentaristas y comunidades.', ['Yama y niyama tratan de relaciones éticas y observancias personales.','Āsana y prāṇāyāma son dos partes dentro de un sistema más amplio.','Dharana, dhyana y samadhi describen aspectos relacionados de la atención.'],'Construye tu rueda de ocho miembros','Relacionar ideas filosóficas con hábitos concretos de enseñanza.', ['Asocia cada miembro con una práctica cotidiana observable.','Elige uno que suela quedar fuera de tus clases.','Diseña una pregunta para invitar a explorarlo sin imponer creencias.'],'Una rueda con ocho ejemplos prácticos.','¿Qué parte del modelo me resulta más difícil llevar a la vida diaria?','¿Cuál NO es uno de los ocho miembros tradicionalmente enumerados en los Yoga Sutras?',['Yama','Niyama','Bhakti','Dharana'],2,'Bhakti yoga aparece en otras tradiciones y textos, pero no forma parte de la enumeración clásica de ocho miembros de los Yoga Sutras.'),
      lesson('yamas-niyamas','Yamas y niyamas: ética aplicada',18,'La ética de un profesor no se limita a lo que dice al inicio de la clase: se expresa en decisiones, límites, comunicación y cuidado del poder que ocupa.','Los yamas se suelen traducir como disciplinas relacionales —ahimsa, satya, asteya, brahmacharya y aparigraha—; los niyamas, como observancias personales —śaucha, santoṣa, tapas, svādhyāya e īśvara-praṇidhāna—. Las traducciones dependen del comentario y del contexto. Úsalos como preguntas de reflexión, no como instrumentos de culpa.', ['Ahimsa no significa evitar todo esfuerzo; implica no glorificar el daño.','Satya invita a hablar con honestidad y calibrar lo que se afirma.','Svādhyāya puede incluir estudio, autoobservación y revisión de sesgos.'],'Laboratorio de dilemas','Ensayar decisiones éticas antes de que aparezcan en clase.', ['Lee el caso: una alumna siente dolor, pero el grupo celebra llegar más lejos.','Formula una respuesta que priorice seguridad sin avergonzarla.','Reescribe una frase competitiva en una invitación neutral.'],'Tres respuestas docentes y el principio que las orienta.','¿Cómo reacciono cuando mis valores chocan con la expectativa de agradar?','En una clase, ¿qué uso más constructivo tienen los yamas y niyamas?',['Evaluar la superioridad moral del alumnado.','Ofrecer marcos para la reflexión y las decisiones cotidianas.','Sustituir la evaluación de seguridad.','Exigir que todos compartan una creencia.'],1,'Son marcos filosóficos para orientar la práctica y la conducta; no autorizan a juzgar a los estudiantes.'),
      lesson('yoga-sutras','Leer los Yoga Sutras con contexto',18,'Los Yoga Sutras son aforismos breves cuya interpretación requiere traducción, comentario y conciencia del marco filosófico en que surgieron.','El texto se organiza tradicionalmente en cuatro pādas: Samādhi, Sādhana, Vibhūti y Kaivalya. El segundo sutra suele traducirse como la aquietación o restricción de las fluctuaciones de la mente, aunque las traducciones no son idénticas. No conviene atribuir a un aforismo una promesa médica ni aislar una frase de su sistema conceptual.', ['Compara traducciones y comenta qué decisiones lingüísticas cambian.','Distingue la traducción literal de la interpretación moderna.','Presenta la incertidumbre como parte legítima del estudio.'],'Lectura comparada','Desarrollar criterio sin convertir una traducción en dogma.', ['Escoge un sutra de una edición fiable.','Compara dos traducciones y marca los términos que cambian.','Escribe qué interpretación puede defenderse y qué parte sigue abierta.'],'Ficha de lectura: texto, traducciones, contexto y preguntas.','¿Qué hago cuando una cita popular contradice el contexto del texto?','¿Por qué conviene leer los sutras con traducciones y comentarios?',['Porque un aforismo breve siempre es inequívoco.','Porque el texto es idéntico a un manual moderno de posturas.','Porque el idioma, el contexto y los comentarios influyen en la interpretación.','Para encontrar promesas universales de salud.'],2,'Los textos aforísticos suelen ser compactos y dependen del idioma y de la tradición interpretativa.'),
      lesson('philosophy-in-class','Traducir filosofía en una clase real',14,'Una enseñanza filosófica respetuosa abre posibilidades de reflexión y no presupone que todas las personas compartan la misma espiritualidad.','Puedes introducir una idea mediante una pregunta, un silencio o una intención sencilla, y ofrecer una salida neutral a quien no desee participar. Por ejemplo, hablar de atención y elección puede inspirarse en svādhyāya sin afirmar que todo el grupo deba aceptar una doctrina metafísica.', ['Formula invitaciones, no afirmaciones sobre la vida interior del alumnado.','Evita usar la filosofía para invalidar dolor, enfado o límites personales.','Conecta el concepto con una acción concreta y opcional.'],'Intención con opciones','Crear una apertura de clase inclusiva y coherente.', ['Elige un valor como atención, honestidad o no competición.','Escribe una intención de dos frases sin exigir una creencia.','Añade una alternativa para quien prefiera practicar en silencio.'],'Un guion de apertura de 30 segundos.','¿Mi lenguaje invita a explorar o indica cómo debería sentirse alguien?','¿Qué convierte una intención filosófica en una invitación inclusiva?',['Exigir una interpretación espiritual concreta.','Conectar una idea con una experiencia opcional y permitir distintas respuestas.','Asegurar que la práctica resuelve todos los problemas.','Usar conceptos filosóficos para corregir emociones.'],1,'La enseñanza inclusiva ofrece contexto, elección y espacio para experiencias diversas.'),
    ]
  },
  {
    id: 'history', number: '02', title: 'Historia, tradiciones y cultura', shortTitle: 'Historia', category: 'Humanidades del yoga', icon: '⌘', level: 'Fundamentos', hours: 12,
    summary: 'Sitúa el yoga en sus contextos: fuentes antiguas, desarrollos medievales, modernidad, yoga postural y responsabilidad cultural al enseñar.',
    outcomes: ['Reconocer que el yoga cambia a través del tiempo.', 'Nombrar fuentes históricas sin simplificarlas.', 'Comunicar la procedencia cultural con respeto y precisión.'],
    lessons: [
      lesson('early-sources','Fuentes antiguas: Vedas y Upanishads',14,'Las referencias antiguas al yoga forman parte de contextos rituales, filosóficos y contemplativos muy distintos del estudio moderno en una esterilla.','Los Vedas, las Upanishads, la Bhagavad Gītā y los Yoga Sutras son fuentes diferentes, surgidas en periodos y contextos diferentes. No deben ordenarse como si cada texto fuera simplemente una edición del anterior. La palabra yoga aparece con sentidos diversos y los historiadores discrepan en cronologías precisas.', ['Distingue entre fuente primaria y resumen contemporáneo.','Evita fechas excesivamente exactas cuando la evidencia no las permite.','Relaciona un texto con su contexto en lugar de tratarlo como una lista de citas.'],'Línea temporal crítica','Construir una cronología sin borrar las diferencias.', ['Coloca cuatro fuentes en una línea temporal aproximada.','Añade una idea o práctica vinculada a cada fuente.','Marca con un asterisco cualquier fecha o relación que deba verificarse.'],'Una línea temporal con notas de incertidumbre.','¿De dónde procede la historia del yoga que aprendí inicialmente?','¿Qué afirmación histórica es más prudente?',['El yoga ha tenido una única forma estable durante miles de años.','Las fuentes deben leerse en su contexto y sus cronologías pueden ser aproximadas.','Todos los textos clásicos fueron escritos a la vez.','Las prácticas contemporáneas son idénticas a las antiguas.'],1,'Las tradiciones se transmiten y transforman; las fuentes tienen contextos y cronologías diferentes.'),
      lesson('bhagavad-gita','La Bhagavad Gītā y los caminos del yoga',14,'La Bhagavad Gītā presenta el yoga a través de un diálogo situado en una crisis moral; no es un manual neutral de ejercicios.','En la Gītā se exploran formas de actuar, conocer, meditar y orientar la devoción, a menudo llamadas karma yoga, jñāna yoga, dhyāna yoga y bhakti yoga. Los capítulos y tradiciones interpretativas dan distintos énfasis a estos caminos. Una presentación responsable evita convertirlos en etiquetas rígidas de personalidad.', ['Karma yoga conecta acción y desapego del fruto en su marco filosófico.','Jñāna yoga enfatiza conocimiento y discernimiento.','Bhakti yoga enfatiza devoción; no es una obligación espiritual para todo estudiante.'],'Cuatro lentes sobre una decisión','Relacionar los conceptos con dilemas sin simplificarlos.', ['Elige un dilema cotidiano de responsabilidad.','Descríbelo desde acción, conocimiento, contemplación y devoción.','Anota qué matiz se pierde al reducir cada camino a una frase.'],'Una comparación de cuatro perspectivas.','¿Cómo puedo presentar una tradición sin pedir que el alumnado la adopte?','¿Qué describe mejor la Bhagavad Gītā?',['Un manual moderno de alineación.','Un diálogo filosófico que aborda acción, conocimiento, meditación y devoción.','Un texto escrito exclusivamente sobre anatomía.','Un sistema idéntico a todas las escuelas de yoga.'],1,'La Gītā es una obra filosófica y religiosa compleja, interpretada de diversas maneras.'),
      lesson('hatha-history','Del haṭha yoga al yoga postural moderno',18,'El yoga postural actual tiene historia propia: bebe de fuentes anteriores, pero también se configuró mediante intercambios modernos, gimnasia, cultura física y redes globales.','Textos medievales como la Haṭha Yoga Pradīpikā describen prácticas corporales, respiratorias y contemplativas que no son idénticas a una clase de flow contemporánea. En los siglos XIX y XX, escuelas, maestros, instituciones y contextos políticos transformaron las prácticas. No existe una única línea sencilla e ininterrumpida que explique todas las clases actuales.', ['No atribuyas automáticamente toda postura actual a la antigüedad.','Distingue continuidad, reinterpretación e innovación.','Presenta a las personas y comunidades implicadas en su contexto.'],'Desmontar un mito histórico','Aprender a verificar narrativas populares del yoga.', ['Anota una frase histórica que hayas escuchado.','Busca qué fuente primaria o investigación podría sostenerla.','Reescribe la frase incluyendo matices y límites.'],'Una ficha de mito, fuente, evidencia y formulación corregida.','¿Por qué me atraen las historias lineales de una tradición antigua?','¿Qué describe con mayor precisión el yoga postural moderno?',['Una forma que no ha cambiado desde una fecha antigua.','Un desarrollo histórico influido por diversas tradiciones y contextos modernos.','Una práctica sin relación con fuentes anteriores.','Una disciplina cuya historia no puede estudiarse.'],1,'La práctica contemporánea recoge influencias antiguas y modernas, con continuidades y cambios.'),
      lesson('lineages','Linajes, estilos y diversidad de métodos',12,'Hatha, Vinyasa, Ashtanga, Iyengar, Yin y otros nombres describen métodos y comunidades diversas; sus etiquetas no garantizan una experiencia uniforme.','Un estilo puede diferenciarse por el ritmo, las secuencias, el uso de apoyos, la respiración, el énfasis pedagógico o su historia institucional. Dos profesores con la misma etiqueta pueden enseñar de manera distinta. Pregunta por fuentes, formación y propósito del método antes de presentar afirmaciones absolutas.', ['Describe el método mediante características observables.','No ordenes estilos en una escala universal de superioridad.','Reconoce cuándo combinas influencias de varios linajes.'],'Comparativa sin jerarquías','Elegir lenguaje claro para comunicar el enfoque de una clase.', ['Compara dos métodos mediante ritmo, estructura, apoyos y énfasis.','Añade una fortaleza y una limitación contextual de cada uno.','Redacta una descripción de tu estilo sin prometer resultados absolutos.'],'Una ficha comparativa y una descripción de clase.','¿Qué estilo me identifica y qué partes de su historia necesito estudiar mejor?','¿Cómo conviene comparar estilos de yoga?',['Decidir cuál es superior para todo el mundo.','Comparar características, contexto, objetivos y límites.','Asumir que el nombre garantiza la misma práctica.','Evitar toda referencia histórica.'],1,'Las comparaciones concretas e históricas son más útiles que las jerarquías universales.'),
      lesson('cultural-responsibility','Respeto cultural, fuentes y lenguaje',16,'Enseñar una práctica con raíces surasiáticas requiere algo más que reproducir palabras: importa cómo se cita, cómo se representa y a quién se atribuye conocimiento.','La apropiación cultural no se resuelve con una lista simple de prohibiciones. Conviene estudiar fuentes de personas y comunidades vinculadas, nombrar influencias, evitar exotizar símbolos y no fingir autoridad lingüística o religiosa. Puedes reconocer aportaciones de forma concreta y mantener una posición de aprendizaje continuo.', ['Atribuye conceptos, textos y métodos cuando la fuente sea conocida.','Evita describir una cultura como estática, misteriosa o homogénea.','No uses sánscrito ni símbolos como decoración sin comprender su uso.'],'Auditoría de una clase','Revisar decisiones de lenguaje, símbolos y atribución.', ['Revisa una descripción de clase o publicación propia.','Marca exotización, promesas grandilocuentes y fuentes ausentes.','Reescribe dos frases y añade una referencia verificable.'],'Una lista de mejoras culturales y de atribución.','¿Qué comunidades y voces no aparecen en mi bibliografía?','¿Qué acción concreta muestra responsabilidad cultural?',['Usar símbolos sin conocer su significado.','Afirmar que todas las tradiciones son iguales.','Citar fuentes, nombrar influencias y seguir aprendiendo.','Presentarse como autoridad de una tradición sin formación.'],2,'La atribución, el contexto y la disposición a seguir aprendiendo son prácticas concretas de respeto.'),
    ]
  },
  {
    id: 'biomechanics', number: '03', title: 'Anatomía y biomecánica aplicada', shortTitle: 'Anatomía', category: 'Anatomía y fisiología', icon: '⌬', level: 'Técnico', hours: 22,
    summary: 'Comprende articulaciones, columna, cadera, hombro, carga, movilidad, estabilidad y variabilidad anatómica sin diagnosticar ni buscar una forma corporal universal.',
    outcomes: ['Nombrar estructuras musculoesqueléticas relevantes para asana.', 'Diferenciar movilidad, estabilidad, fuerza y tolerancia a la carga.', 'Adaptar una práctica con observación y comunicación.'],
    lessons: [
      lesson('movement-language','Planos, ejes y vocabulario del movimiento',16,'El vocabulario anatómico reduce la ambigüedad: permite describir movimientos con mayor precisión y evita que palabras como “abrir” o “alinear” signifiquen cosas distintas para cada persona.','Los planos sagital, frontal y transversal ayudan a describir movimientos; flexión, extensión, abducción, aducción y rotación describen acciones articulares. Son herramientas, no juicios estéticos. Un movimiento real combina planos y depende de la articulación observada: la rotación de cadera no es lo mismo que la rotación de toda la pelvis.', ['Nombra la articulación y la acción, no solo la forma externa.','Distingue el movimiento de una articulación del movimiento global.','Comprueba si la indicación se entiende antes de añadir más instrucciones.'],'Diccionario en movimiento','Entrenar la observación anatómica sin tocar al alumnado.', ['Observa una sentadilla cómoda y describe cadera, rodilla y tobillo.','Repite con una elevación de brazos y observa hombro y escápula.','Sustituye dos indicaciones vagas por términos comprensibles.'],'Cinco observaciones y cinco indicaciones más precisas.','¿Qué palabras mías son demasiado vagas para orientar movimiento?','¿Cuál es una ventaja del vocabulario anatómico?',['Hace que todas las personas deban moverse igual.','Permite describir qué articulación se mueve con mayor precisión.','Elimina la necesidad de escuchar al estudiante.','Predice el dolor a partir de una postura.'],1,'El lenguaje anatómico mejora la descripción, pero no determina una forma correcta única ni permite diagnosticar.'),
      lesson('spine-core','Columna, pelvis y control del tronco',18,'La columna es una estructura móvil con curvas naturales; una clase segura no busca borrar esas curvas, sino explorar el movimiento y la carga dentro de opciones tolerables.','La región cervical, torácica y lumbar tiene características distintas. La pelvis puede inclinarse y rotar, y el tronco coordina respiración, fuerza y movimiento. “Neutral” es una referencia útil en ciertas tareas, no una única posición perfecta para todas las personas o todos los momentos de una práctica.', ['Las curvas de la columna son normales.','La flexión y extensión no son intrínsecamente dañinas: importan dosis, carga y contexto.','El control del tronco no implica mantenerlo rígido en todo momento.'],'Laboratorio columna-pelvis','Notar movilidad y control sin perseguir amplitudes máximas.', ['En postura cómoda, explora pequeñas basculaciones pélvicas.','Añade movimiento suave de columna sincronizado con respiración natural.','Observa si la consigna requiere menos rango o más apoyo.'],'Un diario de sensaciones y variantes tolerables.','¿Confundo “estabilidad” con inmovilidad?','¿Qué afirmación es más adecuada sobre la columna?',['Debe mantenerse rígida siempre.','Las curvas normales deben eliminarse.','Tiene regiones con funciones diferentes y una variabilidad normal.','La forma externa permite diagnosticar lesiones.'],2,'La columna es una estructura dinámica; la práctica debe adaptarse a la persona y a la tarea.'),
      lesson('hip-anatomy','Cadera: movilidad, estabilidad y variabilidad',16,'Las posturas de apertura de cadera no son una prueba de flexibilidad ni una medida de mérito. La estructura ósea y los tejidos varían, por lo que una forma puede sentirse diferente entre personas.','La cadera es una articulación esferoidea; su movimiento incluye flexión, extensión, abducción, aducción y rotaciones. La pelvis y la columna pueden acompañar un movimiento, a veces de manera útil y a veces ocultando que la consigna no se ajusta al objetivo. El límite percibido puede cambiar por geometría ósea, tejidos, control y experiencia.', ['Las diferencias estructurales pueden limitar rangos distintos sin indicar un problema.','Más amplitud no equivale automáticamente a más salud o progreso.','Usa soportes y modifica ángulos antes de forzar una sensación intensa.'],'Tres variantes, un objetivo','Diseñar opciones de una misma postura para cuerpos diferentes.', ['Elige una postura que requiera rotación o flexión de cadera.','Crea tres versiones cambiando apoyo, profundidad o orientación.','Define qué experiencia busca cada versión sin clasificarla por dificultad moral.'],'Tres opciones y el objetivo funcional de cada una.','¿Qué presuposiciones hago sobre movilidad al observar un cuerpo?','¿Qué explica parte de la variación de rango de la cadera?',['Todas las caderas comparten exactamente la misma geometría.','Solo la voluntad limita el rango.','La anatomía, el control, el contexto y la experiencia contribuyen al rango.','Una mayor amplitud siempre es mejor.'],2,'La variabilidad anatómica es normal y requiere opciones, no comparación.'),
      lesson('shoulder-wrist','Hombros, escápulas y muñecas',18,'Las posturas con carga en manos o brazos combinan la acción del hombro, la escápula, el codo, la muñeca y el tronco. Observar el sistema completo es más útil que fijarse en una sola forma.','La escápula se mueve sobre la caja torácica; no necesita permanecer “abajo y atrás” en todos los movimientos. La muñeca soporta carga en extensión en planchas y apoyos, pero la tolerancia varía. Reducir palanca, elevar las manos, usar puños o antebrazos y descansar puede modificar la demanda sin abandonar el objetivo general.', ['La escápula necesita moverse para acompañar elevación del brazo.','Adapta la carga de muñeca mediante altura, apoyo y duración.','Sensación muscular de esfuerzo y dolor punzante no son equivalentes.'],'Escalera de carga','Aprender a reducir o aumentar demanda de forma gradual.', ['Compara apoyo de manos en pared, mesa y suelo solo si te resulta cómodo.','Observa cambios en muñeca, hombro y tronco.','Describe qué variable cambió: inclinación, palanca, carga o tiempo.'],'Una tabla de tres niveles y sus variables de carga.','¿Qué opciones daría antes de pedir a alguien que “aguante”?','¿Qué principio ayuda a adaptar un apoyo de brazos?',['Aumentar duración aunque haya dolor.','Modificar inclinación, palanca, apoyo o tiempo según tolerancia.','Inmovilizar siempre la escápula.','Afirmar que la misma variante sirve a todos.'],1,'La carga puede graduarse modificando parámetros y atendiendo a la respuesta de la persona.'),
      lesson('muscle-tendon-load','Músculos, tendones y adaptación a la carga',18,'La sensación de estiramiento, el esfuerzo y el dolor son experiencias distintas. Una enseñanza responsable evita traducir cada sensación en una afirmación sobre tejidos que no puede observar directamente.','Los músculos generan fuerza, los tendones transmiten fuerzas y el tejido se adapta al estímulo con tiempo y recuperación. La carga tiene dimensiones como intensidad, volumen, velocidad y frecuencia. Ni el dolor demuestra automáticamente lesión ni su ausencia garantiza que cualquier carga sea adecuada: importan el contexto, la evolución y la comunicación.', ['La adaptación requiere dosis y recuperación, no solo intensidad.','El estiramiento no “alarga” de forma instantánea una estructura en un sentido simple.','Escala la demanda y registra respuestas a lo largo del tiempo.'],'Registro de tolerancia','Practicar una progresión de carga de baja complejidad.', ['Elige una acción sencilla, como una elevación de talones.','Modifica repeticiones o apoyo, cambiando solo una variable.','Registra esfuerzo, comodidad y recuperación posterior.'],'Una progresión de tres pasos con criterios para detenerse.','¿Qué ideas heredadas tengo sobre “romper límites” y flexibilidad?','¿Qué suele favorecer una adaptación de carga sostenible?',['Subir todas las variables al máximo de inmediato.','Ignorar la recuperación.','Ajustar estímulo gradualmente y observar la respuesta.','Usar el dolor como objetivo obligatorio.'],2,'La dosis progresiva, la recuperación y el seguimiento importan en el entrenamiento.'),
    ]
  },
  {
    id: 'asana', number: '04', title: 'Asana: familias, función y opciones', shortTitle: 'Asana', category: 'Técnicas y práctica', icon: '⌁', level: 'Práctico', hours: 20,
    summary: 'Estudia posturas de pie, flexiones, extensiones, torsiones, equilibrios e inversiones por su intención, requisitos, transiciones y opciones.',
    outcomes: ['Explicar la función de una postura más allá de su silueta.', 'Proponer variaciones y apoyos para el mismo objetivo.', 'Reconocer señales para pausar, reducir rango o cambiar de postura.'],
    lessons: [
      lesson('standing-poses','Posturas de pie: base y distribución de carga',14,'Las posturas de pie permiten explorar base de apoyo, equilibrio, fuerza y orientación espacial. No todas las personas necesitan colocar los pies en el mismo ángulo o separación.','Tadasana, Virabhadrasana y Trikonasana son familias de referencias técnicas, no moldes universales. Revisa la base de apoyo, la orientación de rodillas y pies, el espacio disponible y la capacidad de mantener una respiración cómoda. Una silla o una pared puede ampliar el acceso a la práctica.', ['Ofrece un rango de separación y orientación de pies.','Observa comodidad, equilibrio y capacidad respiratoria.','No fuerces una rodilla a seguir una línea ideal si la base necesita ajuste.'],'Taller de bases','Comparar estabilidad cambiando una sola variable.', ['Explora una postura de pie con base corta, media y amplia.','Usa pared o silla si mejora equilibrio y confianza.','Registra qué ajustes facilitan control sin añadir dolor.'],'Tres configuraciones posibles con criterios de elección.','¿Qué postura se beneficia de más espacio, apoyo o menos duración?','¿Qué define mejor una buena adaptación de una postura de pie?',['Copiar exactamente el modelo del profesor.','Ajustar base y orientación a objetivo, comodidad y estabilidad.','Bloquear las rodillas en todas las personas.','Forzar más profundidad en cada repetición.'],1,'La postura debe adaptarse a la persona, al objetivo y a las condiciones del espacio.'),
      lesson('forward-folds','Flexiones: longitud, apoyo y ritmo',14,'En una flexión hacia delante, las sensaciones cambian según la posición de rodillas, caderas, pelvis y columna. No es necesario tocar el suelo para que la práctica tenga sentido.','Las flexiones pueden distribuirse entre caderas y columna de distintas formas. Flexionar ligeramente las rodillas, elevar las manos sobre bloques o apoyar el torso puede reducir demanda o cambiar la experiencia. Evita prometer que una flexión “desintoxica” órganos o que toda tensión posterior es una señal deseable.', ['El objetivo no es alcanzar una distancia concreta.','Usa apoyos para reducir tensión o facilitar una pausa.','Sal de la postura de manera lenta si aparece mareo o malestar.'],'Flexión con tres apoyos','Explorar cómo cambia la experiencia al modificar apoyo.', ['Compara manos sobre bloques, silla o muslos.','Prueba rodillas algo flexionadas si resulta cómodo.','Observa respiración, esfuerzo y sensación posterior al salir.'],'Un esquema con tres versiones y cuándo elegirlas.','¿Qué lenguaje refuerza la comparación corporal en una flexión?','¿Qué puede ser una modificación razonable?',['Mantener rodillas bloqueadas para todos.','Usar un soporte y ajustar rodillas para encontrar una versión tolerable.','Rebotar para superar resistencia.','Definir éxito por tocar el suelo.'],1,'Las variantes permiten explorar la intención sin convertir la amplitud en criterio de éxito.'),
      lesson('backbends','Extensiones: repartir el movimiento',16,'Las extensiones no consisten en “doblar más la espalda”. La distribución del movimiento entre hombros, columna, caderas y piernas modifica notablemente la carga.','Cobra, esfinge, puente y otras extensiones tienen requisitos distintos. Reducir altura, usar apoyo y priorizar comodidad al respirar son opciones útiles. No es necesario maximizar la compresión lumbar ni retraer los hombros con fuerza. En personas con condiciones médicas o síntomas persistentes, la adaptación individual puede requerir orientación sanitaria.', ['Más altura no equivale a mejor extensión.','Reparte el movimiento y evita una indicación rígida para todas las espaldas.','Sal de la postura ante dolor agudo, hormigueo o pérdida de control.'],'Escalera de extensión','Distinguir intensidad de profundidad.', ['Compara esfinge y cobra baja, solo dentro de un rango cómodo.','Observa qué ocurre al reducir altura y duración.','Formula una indicación que permita elegir entre ambas.'],'Dos variantes y señales para abandonar o modificar.','¿Qué significa para mí progresar en una extensión sin perseguir más rango?','¿Qué criterio tiene prioridad en una extensión?',['Llegar a la máxima altura posible.','Mantener la respiración y una sensación tolerable con opción de salir.','Comprimir la zona lumbar para notar más intensidad.','Imitar la forma exacta de una fotografía.'],1,'La intención y la tolerancia son más importantes que la altura externa.'),
      lesson('twists','Torsiones: rotar sin imponer amplitud',14,'Las torsiones son movimientos combinados. Una persona puede girar de forma distinta según la movilidad de cadera, columna, orientación y apoyos disponibles.','Una torsión sentada no exige usar el brazo como palanca para profundizar. Alargar el tronco, orientar pelvis y caja torácica de forma cómoda y salir sin brusquedad reduce la tendencia a competir por amplitud. Embarazo, cirugía reciente, síntomas o condiciones específicas requieren adaptar la práctica de forma individual y, cuando corresponda, derivar a profesionales sanitarios.', ['Evita usar el brazo para forzar la torsión.','Explora la rotación con respiración cómoda, sin prometer que “exprime toxinas”.','Adapta rango y posición cuando existen condiciones específicas.'],'Torsión sin palanca','Notar diferencia entre orientar y forzar.', ['Haz una rotación suave sentada con manos apoyadas.','Repite con una base de apoyo distinta, sin tirar del brazo.','Describe en qué momento aparece el deseo de forzar.'],'Una breve nota de técnica y lenguaje.','¿Qué frase podría invitar a girar sin convertirlo en una competición?','¿Qué indicación resulta más prudente en una torsión?',['Usa el brazo para llevarte mucho más lejos.','Gira solo hasta donde mantengas control y respiración cómoda.','Las torsiones limpian órganos.','Todas las personas deben alcanzar el mismo ángulo.'],1,'La rotación debe respetar la variabilidad, la comodidad y el contexto de cada persona.'),
      lesson('balances-inversions','Equilibrios e inversiones: riesgo y progresión',18,'Los equilibrios e inversiones exigen valorar experiencia, entorno, posibles consecuencias de una caída y opciones para salir. No son una prueba de valentía ni son indispensables para una práctica completa.','Árbol, media luna, perro boca abajo y variantes invertidas tienen demandas diferentes. Practicar junto a una pared, disminuir el tiempo, apoyar una mano o elegir otra postura puede hacer la actividad más adecuada. Las inversiones con carga sobre cabeza o cuello no deben introducirse sin formación, preparación y evaluación de riesgos pertinente.', ['Primero enseña cómo entrar y salir, no solo la forma final.','Reduce altura y exposición a caídas en aprendices.','No enseñes inversiones complejas fuera de tu competencia formativa.'],'Plan de riesgo y alternativa','Convertir una postura desafiante en una decisión informada.', ['Escoge un equilibrio o inversión habitual.','Escribe requisitos del entorno y una alternativa de menor riesgo.','Añade una señal clara para salir y una opción con pared o silla.'],'Una ficha de decisión con alternativa, salida y límites de competencia.','¿Qué presión social puede llevar a un estudiante a aceptar un riesgo que no desea?','¿Qué debe priorizarse al enseñar un equilibrio o inversión?',['La espectacularidad de la postura.','Una entrada rápida sin explicar la salida.','La evaluación de contexto, una salida segura y alternativas voluntarias.','La idea de que todos deben intentarlo.'],2,'La práctica debe incluir evaluación de riesgo, alternativas y una salida clara.'),
    ]
  },
  {
    id: 'alignment', number: '05', title: 'Alineación, observación y adaptaciones', shortTitle: 'Alineación', category: 'Técnicas y práctica', icon: '⌖', level: 'Práctico', hours: 16,
    summary: 'Aprende a observar a personas reales, hacer preguntas, usar props y modificar la práctica por objetivo, comodidad y contexto, no por una silueta ideal.',
    outcomes: ['Observar de forma descriptiva antes de corregir.', 'Usar accesorios como herramientas, no como marcas de nivel.', 'Ofrecer adaptaciones sin diagnosticar ni avergonzar.'],
    lessons: [
      lesson('observe-first','Observar antes de corregir',12,'La inspección visual no revela por sí sola dolor, lesión, intención ni experiencia. Antes de corregir, define qué observas y si realmente hace falta intervenir.','Una observación descriptiva podría ser “el peso parece desplazarse hacia el borde externo del pie”; una interpretación prematura sería “tienes un problema de cadera”. La observación sirve para adaptar instrucciones y preguntar, no para diagnosticar. En ocasiones la mejor intervención es no intervenir.', ['Describe comportamiento observable, no supuestas causas.','Pregunta en privado y sin presuponer malestar.','Prioriza las intervenciones que sean relevantes para el objetivo y la seguridad.'],'Observación neutra','Separar evidencia, interpretación y acción docente.', ['Observa una postura sin intentar nombrar un defecto.','Anota tres hechos visibles.','Escribe una pregunta respetuosa antes de sugerir un ajuste.'],'Una ficha: observación, pregunta, opción y seguimiento.','¿Qué emociones me despierta ver a alguien practicar distinto a mí?','¿Cuál es un ejemplo de observación neutral?',['Tiene una cadera lesionada.','No está concentrándose.','La mano derecha está apoyada sobre el bloque.','Su postura es incorrecta.'],2,'Una observación neutral describe lo visible sin atribuir causas, diagnóstico ni juicio.'),
      lesson('props','Bloques, cinturón, manta, pared y silla',12,'Los accesorios no son una versión para personas con menos habilidad. Son herramientas para ajustar apoyo, distancia, palanca, comodidad y capacidad de explorar una intención.','Un bloque puede elevar el suelo; un cinturón amplía el alcance sin tirar; una manta puede aportar acolchado; la pared facilita orientación y equilibrio; una silla abre muchas opciones de apoyo. La herramienta se elige según la necesidad del momento y no como indicador del nivel personal.', ['Explica para qué sirve el apoyo antes de ofrecerlo.','Comprueba que el material no resbala y está bien colocado.','Ofrece una opción sin obligar a aceptarla.'],'Una postura, cinco soluciones','Diseñar variaciones funcionales con accesorios.', ['Elige una postura con demanda de equilibrio o alcance.','Crea variantes con dos accesorios distintos.','Describe qué variable modifica cada opción.'],'Una tarjeta de postura con dos adaptaciones explicadas.','¿Cómo puedo presentar los accesorios sin crear jerarquías?','¿Qué principio guía la elección de un accesorio?',['El accesorio demuestra que el alumno no puede.','Debe usarse igual para todos.','Se elige según objetivo, apoyo y preferencias de la persona.','Siempre profundiza la postura.'],2,'Los apoyos son herramientas de adaptación y exploración.'),
      lesson('verbal-cues','Indicaciones claras, breves y accionables',14,'Una buena indicación dirige la atención hacia una acción posible. Las frases largas, las metáforas confusas o la acumulación de órdenes pueden dificultar que el alumnado practique con autonomía.','Prioriza una instrucción por vez, usa verbos observables y deja espacio para probar. “Presiona el suelo suavemente con los pies” ofrece una acción; “activa todo y alinea perfectamente” no especifica qué hacer. Confirma la comprensión mediante observación y preguntas, no repitiendo la misma frase más alto.', ['Usa verbos concretos y una sola prioridad por intervención.','Da tiempo a que la clase procese la indicación.','Comprueba qué efecto produce la consigna en lugar de asumirlo.'],'Taller de edición verbal','Reducir ruido verbal y aumentar autonomía.', ['Graba o escribe una indicación de 30 segundos.','Subraya verbos vagos y órdenes simultáneas.','Reescribe la instrucción en una o dos acciones claras.'],'Una indicación concisa y una alternativa más amable.','¿Cuánto silencio dejo para que el alumnado perciba su experiencia?','¿Qué indicación es más accionable?',['Activa todo de la forma perfecta.','Haz que tu energía fluya correctamente.','Apoya los pies y comprueba si puedes respirar sin esfuerzo.','No te equivoques.'],2,'Una indicación observable permite experimentar y comprobar el efecto.'),
      lesson('individual-variation','Variabilidad anatómica y opciones equivalentes',14,'Las personas no comparten las mismas proporciones, historia de movimiento, capacidad, energía ni preferencias. La enseñanza se beneficia al definir el propósito de una postura antes de elegir su forma.','Una adaptación es equivalente cuando conserva el objetivo pedagógico relevante, aunque cambien la forma o los músculos implicados. Por ejemplo, entrenar equilibrio no requiere que todas las personas usen la misma postura. Evita prometer que una variante es terapéutica; describe qué demanda cambia y deja que la persona elija.', ['Diseña dos caminos para el mismo objetivo de aprendizaje.','Adapta rango, duración, soporte y ritmo por separado.','Pregunta qué opción resulta útil y revisa la respuesta.'],'Menú de opciones','Planificar una clase menos dependiente de una forma estándar.', ['Elige el objetivo de una postura: equilibrio, fuerza, movilidad o pausa.','Diseña una versión en suelo y otra con apoyo, o dos niveles de demanda.','Redacta una frase que presente ambas sin hablar de “fácil” y “difícil”.'],'Un menú de tres opciones equivalentes en dignidad.','¿A quién puede excluir mi versión predeterminada de una postura?','¿Cómo se define una adaptación útil?',['Como una versión inferior para principiantes.','Como una opción que ajusta la demanda y conserva un objetivo relevante.','Como una terapia que el profesor puede prescribir.','Como la postura que más se parece a una foto.'],1,'Una adaptación ajusta la práctica a la persona sin convertir la forma original en un estándar moral.'),
      lesson('pain-and-stop','Dolor, incomodidad y decisiones de pausa',16,'El docente no necesita clasificar clínicamente una sensación para responder bien. Puede detener, cambiar o simplificar la actividad y escuchar la experiencia comunicada por el alumno.','El dolor es complejo y no se puede inferir por una expresión facial ni diagnosticar desde la esterilla. Ante dolor agudo, creciente, hormigueo, mareo, falta de aire inusual u otros síntomas preocupantes, detén la actividad y no animes a atravesarlos. Si el síntoma es intenso, persistente o urgente, recomienda valoración sanitaria apropiada; ante emergencia, activa el protocolo local.', ['No uses “es normal” para invalidar lo que siente alguien.','Ofrece salir, descansar o cambiar sin pedir explicaciones públicas.','Reconoce los límites de tu competencia y deriva cuando corresponda.'],'Ensayo de respuesta docente','Practicar lenguaje tranquilo ante un síntoma inesperado.', ['Lee el caso: un alumno informa dolor punzante durante una postura.','Escribe una respuesta inmediata que detenga o modifique la actividad.','Añade cómo seguirías la conversación en privado.'],'Un guion de tres pasos: parar, ofrecer opciones y hacer seguimiento.','¿Puedo escuchar un límite sin intentar convencer a la persona?','¿Cómo debería responder un profesor ante dolor agudo durante una postura?',['Pedir que aguante unas respiraciones más.','Afirmar que el dolor es una liberación emocional.','Detener la actividad, ofrecer opciones seguras y actuar según la gravedad.','Diagnosticar el tejido afectado.'],2,'La prioridad es no forzar, escuchar y reconocer cuándo se necesita evaluación profesional.'),
    ]
  },
  {
    id: 'respiration', number: '06', title: 'Pranayama y fisiología respiratoria', shortTitle: 'Respiración', category: 'Técnicas y práctica', icon: '≈', level: 'Técnico', hours: 14,
    summary: 'Comprende la respiración básica, la atención respiratoria y técnicas tradicionales con progresión prudente, evitando promesas clínicas y retenciones forzadas.',
    outcomes: ['Explicar aspectos básicos de la mecánica respiratoria.', 'Guiar respiración natural sin inducir tensión.', 'Reconocer cuándo omitir una técnica o facilitar una salida.'],
    lessons: [
      lesson('breathing-basics','Mecánica respiratoria esencial',14,'La respiración responde a necesidades metabólicas y también interactúa con la postura, el movimiento, la atención y el estado emocional. La consigna debe permitir que el cuerpo siga respirando con comodidad.','El diafragma participa de forma central en la inspiración; la caja torácica y otros músculos también contribuyen. La respiración no ocurre únicamente en el abdomen, y “respirar al vientre” puede servir como atención sensorial pero no como descripción anatómica completa. El ritmo, la profundidad y la sensación varían entre individuos y situaciones.', ['No impongas una única forma visible de respirar.','La respiración cómoda tiene prioridad frente a acompasar cada movimiento.','Permite que el alumno vuelva a respirar espontáneamente en cualquier momento.'],'Observación sin corrección','Diferenciar observación y control respiratorio.', ['Siéntate cómodamente y observa unas respiraciones sin cambiarlas.','Nota movimiento de costillas, abdomen o espalda sin exigir uniformidad.','Escribe una frase de invitación que no obligue a profundizar.'],'Una descripción y una consigna de atención neutra.','¿Qué ocurre en mí cuando intento controlar demasiado la respiración?','¿Qué describe mejor la mecánica respiratoria?',['El abdomen se mueve por sí solo y el diafragma no participa.','La respiración combina diafragma, caja torácica y otros músculos.','Todas las personas muestran el mismo movimiento abdominal.','La respiración debe hacerse profunda siempre.'],1,'La ventilación involucra varios músculos y movimientos; la forma visible varía.'),
      lesson('breath-awareness','Atención respiratoria y regulación',12,'Observar el aire sin cambiarlo es una habilidad suficiente para una práctica breve. No hace falta convertir cada ejercicio respiratorio en una técnica de control.','La atención puede dirigirse a las fosas nasales, al movimiento de las costillas o a la sensación general de respirar. Para algunas personas, enfocarse en la respiración resulta incómodo o activa ansiedad. Ofrece anclajes alternativos como sonidos, contacto con el suelo o mirada suave, y nunca conviertas la práctica en una prueba de serenidad.', ['La atención respiratoria debe ser opcional.','Permite elegir otro anclaje sensorial.','No prometas regular emociones de la misma forma en todas las personas.'],'Tres anclajes sensoriales','Aprender a dar opciones accesibles de atención.', ['Guía un minuto de observación del aire sin manipularlo.','Repite usando sonidos o puntos de contacto.','Compara qué opción facilita más presencia en este momento.'],'Un guion breve con dos alternativas.','¿Cómo haría espacio a quien no quiera centrar la atención en respirar?','¿Qué es lo más adecuado si el foco respiratorio incomoda a un alumno?',['Insistir hasta que se acostumbre.','Proponer un anclaje alternativo y permitir parar.','Explicarle que está haciendo mal yoga.','Forzar una respiración más lenta.'],1,'Ofrecer elección y alternativas evita convertir la atención en una experiencia obligatoria.'),
      lesson('ujjayi','Ujjayi: lenguaje y dosificación',12,'Ujjayi suele enseñarse como una respiración con estrechamiento suave en la región de la garganta que produce un sonido discreto. No hace falta exagerar el sonido ni generar tensión.','En diferentes linajes, la técnica y su uso varían. Si la persona siente presión, sequedad, mareo o dificultad respiratoria, vuelve a respiración natural. La utilidad pedagógica no depende de que el sonido sea audible desde toda la sala. Evita vincular una frecuencia concreta con efectos garantizados sobre salud o energía.', ['Presenta la técnica como opción, no requisito.','Prioriza comodidad en garganta y respiración continua.','Evita competir por intensidad o volumen del sonido.'],'Guion opcional para Ujjayi','Practicar cómo ofrecer una técnica de manera gradual.', ['Explica brevemente el sonido suave sin forzar la garganta.','Invita a probar dos o tres ciclos como máximo si es cómodo.','Ofrece volver a la respiración espontánea o abandonar la técnica.'],'Una explicación verbal segura de 20 segundos.','¿Qué señal me indicaría que debo simplificar la instrucción?','¿Cómo se presenta Ujjayi con mayor prudencia?',['Con un sonido fuerte obligatorio.','Como una opción suave, sin forzar y con permiso para volver a respirar naturalmente.','Como una técnica que todos deben sostener toda la clase.','Reteniendo el aire al máximo.'],1,'La técnica se enseña gradualmente, con atención a la experiencia y posibilidad de detenerse.'),
      lesson('alternate-nostril','Respiración alterna: secuencia básica y límites',14,'La respiración alterna se utiliza en algunas tradiciones como práctica de atención. Su versión más prudente para principiantes es breve, suave y sin retenciones forzadas.','Las instrucciones de mano y el ritmo varían entre escuelas. No necesitas garantizar un cambio fisiológico específico para justificar la práctica: puede estudiarse como técnica tradicional que focaliza la atención. Evítala o adáptala cuando resulte incómoda, haya congestión que dificulte respirar o la persona tenga indicaciones médicas relevantes.', ['Explica el patrón antes de empezar y permite observar sin practicar.','No añadas retenciones ni conteos exigentes para principiantes.','Si aparece mareo o dificultad, para y vuelve a respirar con naturalidad.'],'Diseña una práctica gradual','Crear una guía clara y sin presión.', ['Escribe un guion de 4 ciclos tranquilos sin retenciones.','Incluye una versión de solo observación, sin tapar las fosas nasales.','Añade una salida explícita ante incomodidad.'],'Una pauta breve con opción de observar o parar.','¿Por qué no debería asumir que todas las personas quieren practicar técnicas con las manos en la cara?','¿Qué ajuste es prudente al introducir respiración alterna?',['Añadir retenciones máximas desde el principio.','Hacerla obligatoria para todo el grupo.','Mantenerla breve, opcional y sin esfuerzo ni retención forzada.','Prometer que cura problemas respiratorios.'],2,'La progresión y la opción de no practicar protegen la autonomía y reducen presión.'),
      lesson('breath-retention','Retenciones, hiperventilación y señales de alerta',18,'Las prácticas que alteran mucho el ritmo respiratorio o contienen el aire requieren una formación más especializada y una consideración cuidadosa del contexto y de posibles riesgos.','La hiperventilación puede modificar el dióxido de carbono sanguíneo y provocar hormigueo, mareo u otros síntomas. Las retenciones pueden ser inadecuadas para algunas personas, especialmente sin supervisión competente. Esta plataforma no ofrece una prescripción médica ni sustituye una formación práctica cualificada: en un curso general para docentes, la opción por defecto debe ser no forzar y no retener.', ['No combines respiración rápida intensa con retenciones sin formación específica.','No interpretes hormigueo o mareo como prueba de progreso espiritual.','Ante síntomas, detén la técnica y sigue el protocolo de seguridad.'],'Caso de decisión','Practicar la selección responsable de una técnica.', ['Un alumno informa mareo durante una técnica exigente.','Escribe qué indicarías de inmediato y qué evitarías decir.','Define qué información debería proporcionar un profesional sanitario si la persona consulta.'],'Un protocolo breve de respuesta y derivación.','¿Qué límites técnicos necesito respetar antes de enseñar pranayama avanzado?','¿Qué respuesta es más segura ante mareo durante un ejercicio respiratorio?',['Invitar a seguir porque el cuerpo se está limpiando.','Parar la técnica, facilitar respiración espontánea y valorar la situación.','Aumentar la velocidad.','Diagnosticar la causa sin evaluación.'],1,'Los síntomas exigen interrumpir la técnica, no intensificarla ni atribuirles una explicación no comprobada.'),
    ]
  },
  {
    id: 'meditation', number: '07', title: 'Meditación, atención y relajación', shortTitle: 'Meditación', category: 'Técnicas y práctica', icon: '◍', level: 'Práctico', hours: 12,
    summary: 'Aprende a guiar atención, concentración, observación, descanso y cierre con lenguaje claro, silencios útiles y alternativas para diferentes experiencias.',
    outcomes: ['Distinguir concentración, observación y relajación.', 'Guiar una práctica breve con ritmo y silencios.', 'Ofrecer opciones de postura, mirada y anclaje sensorial.'],
    lessons: [
      lesson('attention-basics','Atención, concentración y observación',12,'Meditar no exige vaciar la mente ni eliminar los pensamientos. En distintas prácticas, la atención se entrena volviendo a un objeto, observando la experiencia o cultivando una cualidad concreta.','Dharana suele traducirse como concentración; dhyana, como meditación o continuidad de la atención. La experiencia real incluye distracciones y cambios. Un docente ayuda a reconocerlos sin convertirlos en fracaso. Los objetivos y definiciones cambian entre tradiciones, por lo que conviene nombrar qué práctica concreta se está guiando.', ['La distracción es parte del entrenamiento de la atención.','Describe la práctica concreta en lugar de prometer “dejar la mente en blanco”.','Permite que el alumno vuelva al anclaje tantas veces como necesite.'],'Un minuto, muchas vueltas','Normalizar la distracción como parte de la experiencia.', ['Elige un sonido, punto visual o contacto como anclaje.','Practica un minuto y nota cuándo la atención se desplaza.','Cada vez que lo adviertas, vuelve sin reproche.'],'Un registro de anclaje, distracciones y retorno.','¿Cómo hablo conmigo cuando me distraigo?','¿Qué actitud facilita entrenar la atención?',['Juzgar cada distracción como fracaso.','Volver al anclaje con amabilidad cuando notes que la atención se desplazó.','Intentar suprimir todos los pensamientos.','Mantener una postura incómoda a toda costa.'],1,'La atención se entrena mediante el reconocimiento y el retorno, no mediante el juicio.'),
      lesson('guided-meditation','Cómo guiar una meditación de cinco minutos',14,'Una guía breve necesita una estructura sencilla: orientación, elección de anclaje, tiempo de silencio y cierre. Hablar sin pausa puede dificultar que el grupo explore su experiencia.','Antes de comenzar, indica duración aproximada, postura posible, opción de ojos abiertos y cómo detenerse. Usa frases cortas, da tiempo entre instrucciones y evita afirmar que sabes lo que sienten los participantes. El cierre puede invitar a ampliar la atención a la sala, mover suavemente el cuerpo y volver a la actividad sin prisa.', ['Avisa sobre duración y opciones antes del silencio.','Alterna lenguaje breve y pausas reales.','No interpretes la experiencia interna de otras personas.'],'Escribe y cronometra una guía','Practicar el ritmo y la claridad de la voz docente.', ['Redacta una bienvenida de 20 segundos.','Incluye dos indicaciones de atención y al menos 30 segundos de silencio.','Diseña un cierre gradual, con opción de mantener los ojos abiertos.'],'Un guion de cinco minutos con marcas de pausa.','¿Qué me cuesta más: guardar silencio o no interpretar la experiencia ajena?','¿Qué mejora una práctica guiada?',['Hablar continuamente para evitar silencios.','Anunciar opciones, usar instrucciones breves y cerrar gradualmente.','Prometer que todo el mundo se relajará.','Exigir los ojos cerrados.'],1,'La claridad, la elección y el silencio deliberado ayudan a sostener una práctica guiada.'),
      lesson('restorative-savasana','Savasana y descanso accesible',12,'El descanso también necesita opciones. Permanecer tumbado e inmóvil puede ser agradable para algunas personas e incómodo para otras por motivos físicos, emocionales o culturales.','Savasana se suele usar al final de muchas clases, pero una postura supina no es obligatoria. Se puede ofrecer apoyo bajo las rodillas, postura lateral, asiento o salida de la sala. El docente debe evitar tocar sin consentimiento, narrar emociones supuestamente liberadas o insistir en que alguien “se rinda” si eso genera tensión.', ['Explica opciones de postura y movimiento antes del descanso.','Usa un lenguaje que no obligue a relajarse.','Respeta la salida silenciosa y la preferencia de mantener los ojos abiertos.'],'Diseña tres opciones de descanso','Preparar un cierre accesible para más personas.', ['Escribe una propuesta tumbada con apoyo opcional.','Añade una alternativa de lado o sentada.','Formula un cierre sin ordenar a nadie que cierre los ojos.'],'Un guion accesible para tres formas de descansar.','¿Qué necesito cambiar para no tratar el descanso como una obligación?','¿Qué práctica docente es más inclusiva en Savasana?',['Exigir inmovilidad y ojos cerrados.','Ofrecer opciones de postura y respetar la autonomía.','Tocar a cada alumno para corregirlo sin preguntar.','Afirmar que todo el mundo necesita el mismo descanso.'],1,'La opción y el consentimiento importan incluso en las prácticas de descanso.'),
      lesson('meditation-trauma-aware','Atención sensible a experiencias diversas',16,'Una práctica de atención puede ser intensa o desagradable para algunas personas. No es posible prever toda reacción, pero sí reducir la presión y ofrecer alternativas claras.','Un enfoque sensible a experiencias diversas enfatiza elección, transparencia, predictibilidad y agencia. Evita pedir que alguien cierre los ojos, se concentre en partes del cuerpo o comparta experiencias personales. No necesitas etiquetar la práctica como terapia ni asumir que el yoga resuelve trauma. Si surge malestar, ofrece orientación al entorno, movimiento o salida según preferencia.', ['Ofrece ojos abiertos, externos o un anclaje neutro.','No pidas revelar trauma o emociones delante del grupo.','No presentes una clase general como tratamiento psicológico.'],'Reescribe una guía','Cambiar órdenes potencialmente invasivas por invitaciones.', ['Revisa una guía que use “debes”, “entrega todo” o “cierra los ojos”.','Convierte cada frase en una opción específica.','Incluye una manera discreta de pausar o salir.'],'Un guion revisado con tres opciones de agencia.','¿Qué lenguaje puede sonar tranquilizador para mí y restrictivo para otra persona?','¿Qué enfoque respeta mejor experiencias diversas?',['Pedir que todos cuenten qué les ha ocurrido.','Ofrecer alternativas, predictibilidad y posibilidad de parar.','Afirmar que el yoga cura trauma.','Interpretar el silencio como consentimiento.'],1,'La elección informada y el respeto por los límites son más importantes que lograr una reacción emocional concreta.'),
      lesson('teach-silence','La voz, el silencio y el cierre',10,'La voz guía la práctica con intención: volumen suficiente, ritmo que permita procesar y silencios que no se sientan como un error que hay que tapar.','El cierre de una clase puede devolver progresivamente la atención al espacio, invitar a moverse y explicar cómo incorporarse. Ajusta el volumen y la velocidad al tamaño del grupo y al entorno. Evita usar música o volumen como sustituto de instrucciones claras y respeta las políticas de accesibilidad, ruido y seguridad del espacio.', ['La pausa puede ser una decisión pedagógica.','Comprueba que las instrucciones se escuchan desde el fondo de la sala.','Cierra con claridad, tiempo y opción para continuar despacio.'],'Prueba de voz','Evaluar legibilidad sin confundir autoridad con volumen.', ['Graba la misma instrucción en un ritmo rápido y otro más pausado.','Escucha si hay palabras redundantes o tecnicismos.','Diseña un cierre de 45 segundos con tres etapas.'],'Audio o guion comparativo con mejora concreta.','¿Qué quiero que las personas se lleven, sin decirles qué deberían haber sentido?','¿Qué caracteriza una voz docente efectiva?',['Hablar alto y rápido durante toda la clase.','Adaptar volumen, ritmo y pausas al contexto y dar un cierre claro.','Usar términos complejos para mostrar autoridad.','Evitar cualquier silencio.'],1,'La voz docente facilita comprensión y autonomía; no necesita llenar cada segundo.'),
    ]
  },
  {
    id: 'sanskrit', number: '08', title: 'Sánscrito, mantra y mudra', shortTitle: 'Sánscrito', category: 'Técnicas y práctica', icon: 'ॐ', level: 'Fundamentos', hours: 12,
    summary: 'Aprende vocabulario de posturas, raíces y transliteración; estudia mantras y mudras con contexto, pronunciación respetuosa y sin afirmaciones pseudocientíficas.',
    outcomes: ['Descomponer nombres comunes de asanas.', 'Pronunciar y usar vocabulario con humildad lingüística.', 'Contextualizar mantras y mudras de diferentes tradiciones.'],
    lessons: [
      lesson('sanskrit-principles','Sánscrito: transliteración y pronunciación',12,'Los nombres en sánscrito conectan la práctica con lenguas y tradiciones vivas. Aprender unas reglas básicas ayuda a nombrar posturas, pero no convierte unas semanas de estudio en competencia lingüística completa.','El sánscrito se escribe tradicionalmente con devanāgarī, aunque en cursos globales también se usa transliteración latina. Marcas como ā, ī, ū, ṛ y consonantes con punto debajo o encima no son decoración: representan distinciones sonoras. Las pronunciaciones varían en comunidades y contextos; escucha fuentes cualificadas y evita ridiculizar acentos.', ['La transliteración representa sonidos y distinciones importantes.','La precisión se mejora escuchando y practicando, no improvisando etimologías.','Nombra la incertidumbre si no conoces el origen de una palabra.'],'Tarjetas de pronunciación','Crear hábito de estudio breve y repetible.', ['Elige cinco términos del curso.','Busca audio de una fuente fiable y registra una aproximación propia.','Marca sonidos que todavía no puedes distinguir.'],'Un glosario personal con audio de referencia o notas fonéticas.','¿Cómo puedo mostrar respeto al pronunciar términos que todavía estoy aprendiendo?','¿Para qué sirve la transliteración?',['Para decorar nombres occidentales.','Para representar en otro sistema de escritura sonidos y distinciones de una lengua.','Para eliminar la necesidad de escuchar hablantes competentes.','Para garantizar que todas las pronunciaciones son idénticas.'],1,'La transliteración ayuda a representar una lengua en otro sistema de escritura, pero no sustituye el aprendizaje de pronunciación.'),
      lesson('asana-etymology','Etimología de nombres de asanas',14,'Descomponer nombres de posturas es una herramienta de memoria, siempre que se distinga una traducción aproximada de una afirmación lingüística segura.','Adho Mukha Śvānāsana se suele traducir como postura del perro con la cara hacia abajo; utthita trikoṇāsana como triángulo extendido; vīrabhadrāsana como postura de Virabhadra. Algunos nombres varían según el linaje, y las segmentaciones populares pueden simplificar gramática o historia. Verifica los términos antes de publicar materiales docentes.', ['Adho significa abajo; mukha, rostro o cara; śvāna, perro; āsana, postura.','Trikoṇa refiere a triángulo y utthita a extendido en nombres comunes.','No inventes traducciones literales si el término es complejo o tiene historia particular.'],'Crea un glosario útil','Memorizar vocabulario para usarlo con claridad en clase.', ['Investiga ocho posturas de tu repertorio.','Añade nombre común, transliteración, significado aproximado y fuente.','Marca términos alternativos entre linajes.'],'Un glosario revisable de ocho posturas.','¿Cómo comunicaría a un grupo que existen varias traducciones de un nombre?','¿Qué significa aproximadamente “utthita” en nombres de posturas?',['Dormido','Extendido','Girado','Sentado'],1,'Utthita suele traducirse como extendido o extendida.'),
      lesson('sanskrit-name-anatomy','Raíces y componentes recurrentes',12,'Reconocer componentes recurrentes hace más fácil recordar nombres largos y entender patrones, pero las palabras compuestas requieren atención al contexto.','Entre componentes comunes aparecen pāda (pie), hasta (mano), ardha (media o mitad), parivṛtta (girado), baddha (atado) y supta (reclinado). Aprende vocabulario con ejemplos de uso y evita reconstruir toda una historia a partir de una raíz aislada.', ['Usa varios ejemplos antes de memorizar una traducción.','Distingue una raíz de la palabra compuesta completa.','Actualiza el glosario cuando una fuente fiable matice tu definición.'],'Rompecabezas de nombres','Aplicar componentes a nombres de posturas.', ['Separa cinco nombres en elementos reconocibles.','Identifica componentes repetidos y posibles sentidos.','Verifica las traducciones con una segunda fuente.'],'Cinco fichas etimológicas con nivel de certeza.','¿Qué diferencia hay entre recordar una raíz y comprender una palabra completa?','¿Qué suele indicar “supta” en nombres de asanas?',['Reclinado','Volador','Hacia abajo','Extendido'],0,'Supta suele referirse a una posición reclinada.'),
      lesson('mantra-context','Mantra y canto: contexto y consentimiento',14,'Los mantras pueden pertenecer a prácticas religiosas, filosóficas y contemplativas específicas. El contexto, la pronunciación y la participación voluntaria importan tanto como el sonido.','Om/ Aum tiene significado y uso en diversas tradiciones de la India; otros mantras tienen textos, deidades, propósitos y contextos propios. No atribuyas al canto un efecto médico garantizado ni obligues a recitar. Puedes explicar el origen conocido, ofrecer escucha silenciosa y permitir una alternativa sin señalar a quien no participa.', ['Explica el contexto de un canto antes de incorporarlo.','La participación vocal debe ser voluntaria.','Distingue significado tradicional, experiencia personal e hipótesis científica.'],'Presentación respetuosa de un mantra','Practicar una introducción informada y no coercitiva.', ['Elige un canto que conozcas bien y estudia su contexto.','Redacta una introducción de dos frases con fuente.','Ofrece opción de escuchar, permanecer en silencio o no participar.'],'Un guion de introducción y una alternativa explícita.','¿Cómo puedo sostener el sentido de una práctica sin imponerla?','¿Qué es esencial antes de invitar a un mantra?',['Exigir que todo el grupo cante.','Presentar contexto, permitir elección y evitar promesas no demostradas.','Afirmar que cura cualquier enfermedad.','Usarlo sin conocer su procedencia.'],1,'La contextualización y la participación voluntaria forman parte de una enseñanza respetuosa.'),
      lesson('mudras-symbols','Mudras: gesto, tradición e interpretación',12,'Los mudras son gestos o sellos empleados en diversas tradiciones, pero sus significados no son universales ni existe una base para atribuir automáticamente poderes específicos a cada colocación de dedos.','Jñāna o chin mudra se representan a menudo con pulgar e índice en contacto; añjali mudra une las palmas. Las interpretaciones varían por tradición. Puedes enseñarlos como gesto simbólico, foco táctil o componente de una práctica y explicar con cuidado cuándo una interpretación procede de una fuente concreta.', ['Pregunta si la posición de manos es cómoda.','Evita asegurar que un mudra dirige energía de manera medible sin evidencia adecuada.','Ofrece una posición neutral de manos como alternativa.'],'Catálogo de gestos con contexto','Evitar que el simbolismo se convierta en afirmación universal.', ['Investiga tres mudras y sus contextos de uso.','Registra una interpretación atribuida a una fuente concreta.','Añade una alternativa cómoda para manos sensibles.'],'Tres fichas con origen, uso y límites de interpretación.','¿Qué palabras usaría para distinguir una creencia tradicional de una evidencia biomédica?','¿Cómo se debería presentar el significado de un mudra?',['Como idéntico en todas las culturas.','Como una interpretación contextualizada, con opción alternativa.','Como una cura médica garantizada.','Como algo que nunca debe explicarse.'],1,'Las interpretaciones deben situarse en su tradición, sin universalizar ni prometer resultados clínicos.'),
    ]
  },
  {
    id: 'sequencing', number: '09', title: 'Diseño de secuencias y arquitectura de clase', shortTitle: 'Secuenciación', category: 'Metodología docente', icon: '⇢', level: 'Aplicación', hours: 18,
    summary: 'Construye clases coherentes desde intención y calentamiento hasta pico opcional, integración y cierre; diseña transiciones seguras y adapta el plan en tiempo real.',
    outcomes: ['Estructurar una clase con propósito y progresión.', 'Analizar requisitos y transiciones entre posturas.', 'Planificar alternativas y gestionar el tiempo disponible.'],
    lessons: [
      lesson('class-arc','La arquitectura de una clase completa',16,'Una clase coherente no es una colección de posturas. Organiza la atención, prepara demandas, desarrolla una intención y ofrece una salida gradual.','Una estructura posible incluye llegada, calentamiento, desarrollo, secuencia principal, integración y cierre; no es una fórmula universal. Define un objetivo que pueda expresarse en una frase y comprueba que cada bloque lo sirve. La duración real, el tamaño del grupo, el estilo y la experiencia de alumnos cambian la estructura.', ['La intención debe verse reflejada en las decisiones de contenido.','El pico es opcional: una clase puede no tener una postura espectacular.','Reserva tiempo real para transiciones y descanso.'],'Diseña un arco de 45 minutos','Pasar de una lista de posturas a una experiencia pedagógica.', ['Define un objetivo de movimiento o atención.','Distribuye la duración entre llegada, preparación, desarrollo e integración.','Marca el tiempo para entrar y salir de posturas con apoyos.'],'Un mapa temporal con objetivo y razón de cada bloque.','¿Qué parte de mis clases suele quedarse sin tiempo y por qué?','¿Qué demuestra coherencia en una secuencia?',['Añadir el mayor número de posturas posible.','Relacionar intención, preparación, progresión e integración.','Reservar todo el tiempo para la postura más avanzada.','Usar exactamente el mismo plan con todos los grupos.'],1,'Una secuencia coherente tiene relación entre el propósito y las decisiones de práctica.'),
      lesson('peak-pose','Progresión hacia una postura central',14,'Una postura central puede orientar la preparación, pero no debe convertirse en meta obligatoria. Puedes secuenciar por familias de movimiento, habilidades o tema sin que exista un pico visible.','Analiza los requisitos principales de la postura: movilidad, fuerza, equilibrio, soportes y modo de salida. El calentamiento debe preparar demandas relevantes, no repetir movimientos por rutina. Incluye una alternativa que comparta el objetivo sin replicar exactamente la forma y evita aumentar de forma brusca el rango o la carga.', ['Identifica requisitos observables y evita suponer una única preparación correcta.','Prepara entradas y salidas, no solo la forma final.','La alternativa debe ser parte del plan original, no una improvisación vergonzosa.'],'Secuencia hacia una opción central','Diseñar progresión y alternativa desde el principio.', ['Elige una postura central de complejidad moderada.','Enumera tres requisitos y una transición de entrada y salida.','Diseña una opción alternativa para quien no quiera practicarla.'],'Una mini-secuencia de 10 minutos con alternativa definida.','¿Cómo evitaría que la postura central sea una medida de valor personal?','¿Qué debe analizarse al preparar una postura central?',['Solo su apariencia final.','Requisitos, carga, transición, salida y alternativa.','Solo la música.','La capacidad de todos para realizarla.'],1,'La secuenciación depende de requisitos y contexto; la participación en la postura central debe ser opcional.'),
      lesson('transitions','Transiciones: movimientos, apoyos y continuidad',16,'Las transiciones merecen enseñanza explícita. Pasar de una postura a otra implica cargar, descargar, girar, apoyar y orientar el cuerpo; nombrar solo el destino deja al alumno sin información importante.','Una transición completa identifica el punto de partida, la acción entre posturas, los apoyos, la dirección, el ritmo respiratorio si corresponde y la forma de llegada. Evita imponer que cada movimiento coincida exactamente con una inhalación o exhalación si eso interfiere con comodidad. Considera espacio entre esterillas y variaciones de movilidad.', ['Describe el movimiento que ocurre entre las dos posturas.','Da una instrucción cada vez y deja tiempo de procesamiento.','Ofrece un camino alternativo si la transición requiere carga o equilibrio.'],'Escribe seis transiciones','Transformar nombres consecutivos en instrucciones enseñables.', ['Escoge tres pares de posturas de una clase.','Escribe la acción concreta: pasos, giro, transferencia de peso o descenso.','Añade apoyo opcional y una salida si la transición no resulta cómoda.'],'Seis instrucciones de transición listas para usar.','¿En qué momento de una clase suelo asumir que todo el mundo conoce el movimiento?','¿Qué hace completa una instrucción de transición?',['Solo nombra la postura final.','Describe acción, apoyos, dirección y llegada, con opciones cuando sean útiles.','Acelera el movimiento para mantener ritmo.','Obliga a sincronizar cualquier movimiento con la respiración.'],1,'El alumno necesita saber cómo pasar de una forma a otra, no solo cuál es el destino.'),
      lesson('breath-and-flow','Ritmo, respiración y Vinyasa',12,'Vinyasa puede describir distintas formas de enlazar movimiento y respiración. El ritmo útil depende del grupo, no de mantener una cadencia que deje atrás a parte del alumnado.','Un flujo puede organizarse por respiraciones, frases de movimiento o pausas deliberadas. Si el alumno necesita una respiración adicional para completar un movimiento, permite que ocurra. La claridad y la seguridad importan más que la uniformidad exacta. Prepara también una forma de permanecer en una postura sin seguir el flujo.', ['No sacrifiques control por velocidad.','Respiración y movimiento pueden coordinarse de forma flexible.','Ofrece una opción de baja carga o pausa estática.'],'Diseña un flujo de cuatro pasos','Equilibrar continuidad y claridad.', ['Elige cuatro movimientos conectados con una intención.','Marca dónde ofrecerías una respiración extra o una pausa.','Escribe una opción sin carga en muñecas o sin desplazamiento.'],'Un flujo con ritmo base y una alternativa explícita.','¿Qué señales me dirían que el grupo necesita que baje el ritmo?','¿Qué caracteriza una enseñanza flexible del flujo?',['Todos deben moverse al mismo tempo.','Permitir respiración suficiente, opciones y pausas cuando hagan falta.','No dar explicaciones para no interrumpir el ritmo.','Aumentar la velocidad si el grupo duda.'],1,'El ritmo debe servir a la práctica y a las personas, no al contrario.'),
      lesson('sequencing-scenarios','Secuenciación por objetivo y nivel mixto',16,'Una clase mixta funciona mejor si el objetivo no depende de que cada participante realice idéntica versión. Planificar tres niveles de carga ayuda a responder sin detener constantemente el grupo.','Diseña una opción base, una opción con más apoyo y una opción de mayor demanda, pero evita etiquetar a las personas por niveles rígidos. Las opciones deben explicar qué cambia y para qué. El plan también debe incluir qué hacer si alguien llega con una condición que desconoce, si el espacio es pequeño o si el grupo está más cansado de lo esperado.', ['Prepara alternativas antes de la clase.','Cambia una variable de demanda cada vez cuando sea posible.','Mantén la misma intención global aunque cambie la forma.'],'Plan A, B y C','Preparar una secuencia resiliente ante cambios del grupo.', ['Escoge un bloque de tres posturas.','Crea una alternativa de mayor apoyo y otra de menor demanda.','Anota qué harías si la clase necesita más descansos o menos espacio.'],'Un plan de contingencia con tres caminos y sus límites.','¿Qué parte de mi plan depende demasiado de que todo salga como imaginé?','¿Cuál es la mejor estrategia para un grupo de nivel mixto?',['Crear grupos de categorías rígidas.','Diseñar opciones con distinto apoyo y carga para un objetivo compartido.','Mantener un plan fijo pase lo que pase.','Prometer que cada alternativa es terapéutica.'],1,'Las opciones anticipadas sostienen un objetivo sin exigir que todos practiquen de la misma manera.'),
    ]
  },
  {
    id: 'pedagogy', number: '10', title: 'Metodología, comunicación y práctica docente', shortTitle: 'Pedagogía', category: 'Metodología docente', icon: '✳', level: 'Aplicación', hours: 18,
    summary: 'Aprende a planificar objetivos, observar aprendizaje, gestionar grupos, dar feedback y desarrollar una presencia docente clara sin depender de demostrar cada asana.',
    outcomes: ['Escribir objetivos de aprendizaje observables.', 'Dar instrucciones y feedback específicos.', 'Reflexionar sobre sesiones mediante registros y evaluación formativa.'],
    lessons: [
      lesson('learning-objectives','Objetivos que se puedan observar',12,'Un objetivo de aprendizaje claro dice qué podrá hacer o explicar el estudiante, en qué contexto y con qué criterio. “Conectar con la energía” puede ser una intención personal, pero no permite evaluar competencia docente por sí sola.','Distingue objetivos de proceso —explorar, observar, practicar— de criterios que pueden observarse, como explicar una variante, guiar una transición o identificar cuándo pedir ayuda. Los criterios sirven para mejorar y no para comparar el valor de las personas.', ['Usa verbos concretos: nombrar, explicar, guiar, adaptar, justificar.','Incluye un criterio que describa cómo se demuestra el aprendizaje.','Separa la intención subjetiva de una competencia evaluable.'],'Reescribe los objetivos','Hacer que el aprendizaje se pueda comprobar y acompañar.', ['Escoge tres objetivos vagos de una clase.','Reescríbelos usando un verbo observable.','Añade una evidencia sencilla de aprendizaje para cada uno.'],'Tres objetivos con evidencia y criterio.','¿Qué parte de mi propuesta es una intención y qué parte es un aprendizaje evaluable?','¿Cuál es un objetivo de aprendizaje observable?',['Ser una persona más elevada.','Comprender el universo.','Guiar una transición entre dos posturas ofreciendo una alternativa.','Sentirse siempre relajado.'],2,'Guiar una transición con opción es una conducta demostrable y revisable.'),
      lesson('teach-without-demo','Enseñar sin demostrar cada movimiento',12,'Demostrar ayuda en algunos momentos, pero hacerlo todo el tiempo puede impedir observar a la clase. El docente necesita alternar demostración, observación y lenguaje verbal.','Antes de demostrar, decide qué merece verse y desde qué ángulo. Luego deja que el alumnado practique mientras tú observas, escaneas el espacio y escuchas. Si participas físicamente en una postura, pierdes parte de la capacidad de notar necesidades, transiciones o diferencias de ritmo. La demostración no sustituye una descripción clara.', ['Demuestra lo que realmente necesita una referencia visual.','Ubícate para ver al grupo sin invadir espacio personal.','No asumas que imitar una forma equivale a comprenderla.'],'Plan de observación','Diseñar un bloque en el que puedas ver a los participantes.', ['Elige un bloque de tres posturas.','Marca qué postura demostrarías y dónde dejarías de practicar tú.','Anota qué observarías antes de hablar de nuevo.'],'Un guion docente con momentos de demostrar, observar y dar feedback.','¿En qué momentos mi necesidad de demostrar limita la atención al grupo?','¿Por qué conviene dejar de practicar junto al grupo en ciertos momentos?',['Porque el profesor no debería practicar nunca.','Para poder observar, escuchar y ajustar instrucciones.','Para imponer silencio.','Para evitar preparar la clase.'],1,'Observar al grupo forma parte de la responsabilidad docente.'),
      lesson('feedback','Feedback descriptivo y no humillante',12,'El feedback funciona mejor cuando es específico, oportuno y conectado con el objetivo. Corregir públicamente la apariencia corporal puede generar vergüenza y no mejorar el aprendizaje.','Describe una acción, pregunta por la experiencia y ofrece una opción. En lugar de “lo haces mal”, prueba “si te resulta cómodo, puedes elevar las manos para reducir la tensión; ¿cómo cambia la sensación?”. No es necesario comentar a todas las personas en cada postura; selecciona intervenciones útiles y respeta el silencio.', ['Habla de la acción o estrategia, no del valor del alumno.','Pide permiso antes de una conversación individual sensible.','Valida la elección de no cambiar.'],'Clínica de feedback','Convertir correcciones generales en propuestas concretas.', ['Reescribe cinco frases que suenen críticas o absolutas.','Añade elección o una pregunta de seguimiento.','Revisa que no diagnostiques ni atribuyas intenciones.'],'Cinco ejemplos de feedback en lenguaje neutral.','¿Qué respuesta mía puede hacer que alguien esconda una incomodidad?','¿Qué feedback es más útil?',['Estás mal alineado.','Tu cuerpo no sabe hacer esto.','Prueba a cambiar la altura del apoyo si te resulta cómodo; ¿qué notas?','Todos deberían hacerlo como yo.'],2,'El feedback específico, opcional y basado en observación favorece aprendizaje y autonomía.'),
      lesson('group-management','Ritmo, espacio y gestión del grupo',14,'Una clase bien diseñada considera volumen de voz, accesos, tamaño del espacio, esterillas, materiales, llegadas tardías y salidas. La gestión del grupo es parte de la pedagogía, no un añadido administrativo.','Organiza el espacio para que las personas puedan moverse sin colisiones y para que se escuchen instrucciones. Explica al inicio qué hacer si alguien necesita descanso, si llega tarde o si sale antes. Mantén límites respetuosos en comportamientos que afecten la seguridad y evita usar el tiempo de clase para avergonzar a una persona.', ['Prepara materiales y circulación antes de comenzar.','Establece normas cortas y explícitas para el espacio compartido.','Gestiona interrupciones con calma y sin humillar.'],'Plano de sala','Diseñar una disposición funcional de grupo.', ['Dibuja la distribución de esterillas, accesos y materiales.','Identifica dos puntos de congestión o mala visibilidad.','Escribe una frase para gestionar una llegada tardía sin interrumpir.'],'Un plano y tres acuerdos de convivencia.','¿Qué necesito comunicar para que el alumnado se sienta orientado desde el minuto uno?','¿Qué forma de gestionar una interrupción es preferible?',['Exponer y avergonzar a la persona.','Ignorar un riesgo de seguridad.','Mantener una norma clara y responder con calma y respeto.','Interrumpir la clase para reprochar intenciones.'],2,'Los límites claros pueden sostenerse sin humillación.'),
      lesson('reflective-practice','Diario docente y mejora continua',14,'La docencia mejora cuando se revisan decisiones concretas, no solo cuando se evalúa si la clase “salió bien”. El diario debe ayudar a detectar patrones y probar pequeños cambios.','Tras una sesión, registra qué objetivo se trabajó, qué señales observaste, qué instrucciones funcionaron y qué se modificaría. Evita escribir historias personales del alumnado que no necesitas guardar. Un ciclo de mejora útil elige una pregunta para la próxima clase, prueba un ajuste y revisa la respuesta.', ['Anota hechos observables más que juicios globales.','Protege privacidad y no recopiles datos innecesarios.','Haz un solo experimento de mejora cada vez.'],'Tu plantilla de revisión','Convertir la experiencia en un proceso de aprendizaje acumulativo.', ['Recuerda una clase o una sesión de práctica.','Registra una decisión eficaz, una dificultad y una pregunta abierta.','Elige un solo ajuste que probarás la próxima vez.'],'Una nota de reflexión con un objetivo para la próxima sesión.','¿Qué información guardo que no necesito y debería eliminar?','¿Qué hace útil un diario docente?',['Juzgar toda la clase como buena o mala.','Registrar hechos, preguntas y un ajuste comprobable para la siguiente sesión.','Guardar datos personales innecesarios de alumnos.','Cambiar todo al mismo tiempo.'],1,'La reflexión sistemática convierte la experiencia en mejoras pequeñas y verificables.'),
    ]
  },
  {
    id: 'ethics', number: '11', title: 'Seguridad, consentimiento, inclusión y límites', shortTitle: 'Ética y seguridad', category: 'Esenciales profesionales', icon: '✧', level: 'Esencial', hours: 16,
    summary: 'Integra consentimiento, límites de competencia, inclusión, privacidad, respuesta ante incidentes y comunicación responsable de beneficios.',
    outcomes: ['Solicitar y respetar consentimiento para el contacto físico.', 'Reconocer cuándo adaptar o derivar fuera de la competencia docente.', 'Crear un entorno más inclusivo y proteger datos del alumnado.'],
    lessons: [
      lesson('consent-touch','Consentimiento para ajustes físicos',14,'El contacto físico nunca debe darse por supuesto. Un asentimiento general al entrar en una clase no sustituye el consentimiento específico, informado y revocable en una situación concreta.','Antes de tocar, explica qué pretendes hacer y pregunta si la persona lo desea; espera una respuesta clara. Diseña también una alternativa sin contacto y evita preguntar en un contexto que ejerza presión pública. Una persona puede cambiar de idea en cualquier momento. El consentimiento no habilita movimientos fuera de tu formación o competencia.', ['El silencio no equivale a consentimiento.','Renovar la posibilidad de decir no forma parte de la práctica.','No toques zonas íntimas ni realices manipulaciones para las que no estás cualificado.'],'Guion de consentimiento','Practicar una petición clara y sin presión.', ['Escribe cómo explicarías un ajuste concreto antes de acercarte.','Añade una alternativa sin contacto.','Formula una respuesta natural si la persona dice que no.'],'Un guion con solicitud, alternativa y respuesta al rechazo.','¿Cómo influye mi rol docente en la libertad de una persona para negarse?','¿Qué condición es necesaria para el contacto físico?',['Haber visto a otro docente hacerlo.','Tener consentimiento claro, específico y revocable; además, competencia adecuada.','Interpretar el silencio como aceptación.','Pedir permiso una sola vez al inicio del curso.'],1,'El consentimiento debe ser específico y revocable y no sustituye la competencia técnica.'),
      lesson('scope-and-referral','Límites de competencia y derivación',14,'Un buen profesor de yoga conoce el valor de su práctica y también los límites de lo que puede valorar o tratar. La humildad profesional protege al alumnado y a la propia docencia.','El profesor no diagnostica lesiones, trastornos psicológicos ni afecciones médicas por observar una postura o escuchar una sensación. Puede ofrecer opciones generales de movimiento, preguntar por necesidades relevantes y sugerir consulta con profesionales sanitarios cualificados cuando corresponda. No cambies medicación ni desalientes tratamientos, y activa la respuesta de emergencia local ante una situación urgente.', ['No prometas curar enfermedades o resolver lesiones mediante yoga.','Pregunta qué opciones necesita la persona sin pedir historial innecesario.','Deriva cuando una cuestión excede tu formación y actúa según protocolos ante una emergencia.'],'¿Me corresponde responder?','Entrenar la decisión entre orientar, adaptar y derivar.', ['Clasifica cinco situaciones según entren dentro o fuera del rol docente.','Escribe una frase amable para sugerir consulta profesional.','Define qué harías si los síntomas son urgentes en mitad de clase.'],'Una matriz de competencias con frases de derivación.','¿Qué me impide decir con naturalidad “esto excede mi competencia”?','¿Qué debe hacer un docente ante una consulta médica fuera de su competencia?',['Diagnosticar según la forma de la postura.','Recomendar abandonar el tratamiento.','Reconocer límites y orientar hacia un profesional cualificado cuando proceda.','Prometer una cura con práctica diaria.'],2,'La docencia general no sustituye la valoración clínica ni el tratamiento de profesionales cualificados.'),
      lesson('inclusive-language','Lenguaje inclusivo, cuerpos y accesibilidad',12,'La inclusión se construye en pequeños detalles: cómo describes los cuerpos, qué posiciones consideras por defecto y qué alternativas están preparadas antes de que alguien tenga que pedirlas.','Evita hacer comentarios sobre peso, edad, género, capacidad o apariencia que no sean necesarios para la práctica. Utiliza nombres y pronombres que las personas indiquen, ofrece opciones de postura, apoyo y mirada, y considera barreras físicas, sensoriales, lingüísticas o económicas. No asumas que una discapacidad determina una experiencia concreta: pregunta y escucha.', ['Describe acciones y opciones, no cuerpos “ideales”.','No conviertas una adaptación en espectáculo ni pidas que alguien explique su discapacidad.','La accesibilidad empieza en la planificación, no solo cuando surge una petición.'],'Auditoría de accesibilidad','Revisar una propuesta antes de impartirla.', ['Revisa la descripción de una clase y marca presuposiciones corporales.','Comprueba accesos, volumen, materiales y opciones de descanso.','Añade una alternativa para cada demanda de equilibrio o suelo.'],'Una lista de mejoras concretas para una clase inclusiva.','¿Quién tendría que pedir una adaptación porque yo no la anticipé?','¿Qué práctica favorece un espacio inclusivo?',['Asumir que todos pueden arrodillarse en el suelo.','Dar opciones sin exigir explicaciones personales y revisar barreras.','Usar la misma instrucción para cualquier cuerpo.','Convertir la adaptación en una demostración pública.'],1,'La inclusión combina planificación, elección y respeto a la privacidad.'),
      lesson('privacy-and-safeguarding','Privacidad, datos y protección',12,'Una clase puede implicar información sensible: lesiones comunicadas, adaptaciones, imágenes, datos de contacto o experiencias personales. Solo debe recogerse lo necesario y de forma transparente.','Explica qué información necesitas y para qué, cómo se guardará y quién puede acceder. No fotografíes ni publiques a los participantes sin un permiso separado y adecuado. Evita registrar detalles de salud en notas compartidas, limita el acceso y elimina datos cuando ya no sean necesarios conforme a la normativa aplicable. Ante dudas legales, consulta asesoramiento especializado.', ['Minimiza datos y restringe accesos.','El permiso para asistir no es permiso para fotografiar o publicar.','Cumple la normativa de privacidad y las políticas del espacio donde enseñas.'],'Mapa de datos','Detectar riesgos de privacidad antes de publicar o registrar.', ['Enumera qué datos recogería tu propuesta.','Justifica la necesidad de cada dato y quién lo verá.','Elimina lo que no necesites y diseña un procedimiento de autorización de imágenes.'],'Un inventario mínimo de datos y reglas de acceso.','¿Qué dato personal estoy tentado a pedir por comodidad, no por necesidad?','¿Qué principio es central al gestionar datos de alumnos?',['Recoger toda la información por si acaso.','Publicar fotos si el ambiente parecía cómodo.','Recoger lo necesario, explicar el uso y limitar el acceso.','Guardar datos indefinidamente.'],2,'La minimización y la transparencia son principios básicos de una gestión responsable.'),
      lesson('emergency-readiness','Preparación y respuesta ante incidentes',16,'La seguridad también depende de preparación práctica: conocer el espacio, los contactos, salidas, botiquín y protocolo de emergencias antes de necesitarlo.','Ante un desmayo, dolor intenso, dificultad respiratoria inusual o una lesión importante, detén la actividad y evalúa la situación de acuerdo con tu formación. No muevas a una persona con posible lesión grave salvo que exista peligro inmediato; llama a los servicios de emergencia según protocolo local y sigue instrucciones del personal cualificado. La formación de primeros auxilios es preferible a improvisar.', ['Conoce dirección exacta del espacio y salidas.','No practiques técnicas de emergencia que no conoces.','Registra el incidente por el canal adecuado y protege la privacidad.'],'Plan de seguridad de sala','Preparar un protocolo práctico antes de una emergencia.', ['Anota dirección, contacto de emergencia y acceso de ambulancia.','Identifica quién llama y quién recibe a los servicios si hay equipo.','Revisa cómo detener la clase y despejar el espacio.'],'Una tarjeta de actuación adaptada al lugar real donde enseñarás.','¿Qué datos prácticos no sabría dar ahora mismo si tuviera que pedir ayuda?','¿Qué debe hacerse ante un incidente grave?',['Continuar la clase y observar.','Improvisar un tratamiento clínico.','Detener la actividad y activar el protocolo de emergencia local según la situación.','Mover siempre a la persona al exterior.'],2,'Un protocolo local claro y la actuación dentro de la propia formación son esenciales.'),
    ]
  },
  {
    id: 'practicum', number: '12', title: 'Prácticum, evaluación y desarrollo profesional', shortTitle: 'Prácticum', category: 'Esenciales profesionales', icon: '↗', level: 'Capstone', hours: 22,
    summary: 'Integra la formación en prácticas observadas, planificación, evaluación, portfolio docente, desarrollo profesional y un proyecto final de clase.',
    outcomes: ['Preparar y guiar una mini-clase completa.', 'Evaluar mediante competencias demostrables y reflexión.', 'Crear un plan personal de aprendizaje y desarrollo responsable.'],
    lessons: [
      lesson('microteaching','Microenseñanza: guiar diez minutos',16,'La microenseñanza permite ensayar instrucciones y transiciones en un espacio controlado, recibir feedback y repetir. No sustituye las prácticas supervisadas ni la evaluación presencial cuando son necesarias.','Prepara un segmento con inicio, objetivo explícito, dos o tres acciones y cierre. Ensáyalo con otra persona que pueda expresar su experiencia sin convertirse en un caso clínico. Observa si las instrucciones son audibles, si las opciones aparecen a tiempo y si puedes ver a quienes practican mientras hablan o se mueven.', ['Define un objetivo alcanzable en diez minutos.','Incluye una alternativa y una transición bien explicada.','Pide feedback sobre conductas concretas y repite una parte.'],'Primera microclase','Transformar conocimiento teórico en una práctica docente revisable.', ['Diseña un guion de diez minutos.','Ensaya con una persona voluntaria o grábate en un espacio seguro.','Recoge dos observaciones y decide qué cambiar en la siguiente prueba.'],'Un guion, una reflexión y una segunda versión mejorada.','¿Qué feedback escuché sin defenderme y qué aprendí de él?','¿Cuál es la finalidad principal de la microenseñanza?',['Demostrar una forma corporal perfecta.','Ensayar una habilidad, recibir feedback específico y mejorar con una nueva prueba.','Sustituir toda supervisión profesional.','Evitar que el alumno haga preguntas.'],1,'La práctica breve es un ciclo de ensayo, feedback y revisión.'),
      lesson('assessment-competencies','Evaluar competencias, no solo memoria',14,'La evaluación final de una formación docente debe considerar conocimiento, ejecución, criterio y límites profesionales. Recordar nombres es necesario, pero no demuestra por sí solo que una persona pueda guiar una clase con seguridad.','Combina preguntas de comprensión con tareas aplicadas: explicar una adaptación, diseñar una secuencia, responder a un caso o enseñar un segmento. Explicita los criterios antes de evaluar y permite repetir una habilidad tras recibir feedback cuando el programa lo permita. El certificado de esta aplicación o la finalización de su contenido no equivalen por sí solos a acreditación externa.', ['Evalúa conocimiento y desempeño aplicado.','Comunica criterios de evaluación por adelantado.','Registra qué competencias requieren práctica adicional.'],'Rúbrica transparente','Diseñar una evaluación que sea útil y justa.', ['Elige una competencia docente.','Define tres niveles descriptivos basados en conductas observables.','Añade una vía de mejora y nueva demostración.'],'Una mini-rúbrica con criterios y oportunidades de mejora.','¿Qué evidencias necesito antes de afirmar que alguien domina una habilidad?','¿Qué evaluación refleja mejor la competencia docente?',['Solo contar horas de vídeo.','Combinar conocimiento y demostración aplicada con criterios claros.','Usar una única pregunta de memoria.','Valorar la personalidad del alumno.'],1,'La competencia se demuestra a través de conocimientos y aplicación observable, no solo de tiempo de consumo.'),
      lesson('portfolio','Portfolio docente y reflexión ética',12,'Un portfolio puede mostrar evolución y criterio sin recopilar datos privados de estudiantes. Incluye planificaciones, guiones, reflexiones, feedback autorizado y ejemplos anonimizados cuando sea pertinente.','El portfolio documenta qué intentaste, qué aprendiste y cómo cambiaste. No es necesario publicar fotografías de cuerpos ni testimonios promocionales para mostrar competencia. Solicita permisos específicos cuando corresponda y evita atribuir a tu enseñanza resultados de salud que no puedes verificar.', ['Documenta proceso y revisiones, no solo resultados vistosos.','Anonimiza ejemplos y solicita autorización para usar material de otras personas.','Separa experiencia personal de afirmaciones generales de eficacia.'],'Tu dossier profesional','Ordenar evidencias de aprendizaje de forma responsable.', ['Incluye una planificación, una reflexión y una actividad creada.','Anota qué se modificó después de recibir feedback.','Define qué evidencia falta y cómo vas a conseguirla de forma ética.'],'Un índice de portfolio de cinco piezas.','¿Qué evidencia muestra mejor mi capacidad de adaptar y reflexionar?','¿Qué debe priorizar un portfolio responsable?',['Fotos de alumnos sin permiso.','Promesas de curación.','Evidencias de proceso, reflexión y consentimiento para materiales compartidos.','Solo testimonios promocionales.'],2,'Un portfolio responsable presenta aprendizaje verificable y protege la privacidad.'),
      lesson('professional-path','Desarrollo profesional, comunidad y negocio responsable',14,'Convertir la enseñanza en una actividad profesional requiere claridad en servicios, comunicación, límites, gestión y aprendizaje continuo. Las decisiones empresariales concretas dependen de jurisdicción y modelo de negocio.','Describe qué tipo de clases ofreces, para quién son, qué requisitos hay y qué límites mantiene el servicio. Evita claims médicos no sustentados y no prometas resultados garantizados. En España, revisa obligaciones fiscales, de consumo, privacidad, seguros y normativa local con profesionales cualificados; una app educativa no sustituye asesoramiento jurídico o contable.', ['Comunica el alcance real de tus servicios y formación.','Usa contratos, políticas de cancelación y gestión de datos claras según corresponda.','Continúa estudiando y busca mentoría o supervisión cuando el caso lo requiera.'],'Mapa de desarrollo a 90 días','Convertir la intención profesional en acciones realistas.', ['Define tu público y los límites de tu servicio.','Elige dos competencias que quieras mejorar y cómo las practicarás.','Anota qué profesionales o fuentes consultarás para las obligaciones legales y fiscales.'],'Un plan de aprendizaje de 90 días y una descripción honesta del servicio.','¿Qué promesa comercial estaría tentado a hacer y cómo la reformularía con honestidad?','¿Qué práctica favorece una actividad profesional responsable?',['Prometer resultados garantizados.','Presentar el servicio y sus límites con transparencia y seguir formándose.','Tratar asesoramiento legal como una opinión personal.','Evitar explicar cancelaciones y privacidad.'],1,'La transparencia sobre alcance, formación y obligaciones favorece una práctica profesional responsable.'),
      lesson('final-capstone','Proyecto final: diseña, guía y revisa una clase',24,'El proyecto final reúne filosofía, anatomía, asana, respiración, secuenciación, pedagogía y ética. La excelencia no significa que todo sea perfecto a la primera: significa justificar decisiones, observar lo que ocurre y corregir el plan.','Prepara una clase completa para un grupo y una duración concretos. Declara una intención alcanzable, justifica la progresión, escribe las transiciones, incluye variaciones y apoyos, propone un cierre y define cómo responderás ante dolor, mareo o alguien que no desea participar en un elemento. Después, enseña un segmento y registra feedback.', ['Explicita propósito, población, duración y supuestos.','Incluye una ruta alternativa y una salida segura en los bloques exigentes.','Evalúa lenguaje, ritmo, consentimiento, inclusión y coherencia.'],'Proyecto integrador','Demostrar decisiones docentes coherentes en un plan completo.', ['Diseña una clase de 45–60 minutos con tiempos realistas.','Revisa cada transición y añade dos opciones por bloque relevante.','Ensaya 10 minutos, recoge feedback y documenta tres cambios para la siguiente versión.'],'Un plan de clase, un guion parcial, una revisión de seguridad y una reflexión.','¿Qué decisiones puedo justificar y cuáles debo investigar o practicar más?','¿Qué define un buen proyecto final de docencia?',['Que cada alumno realice la misma postura.','Que la clase tenga posturas avanzadas.','Que exista coherencia, opciones, seguridad, criterio y reflexión basada en práctica.','Que el guion sea largo aunque no pueda aplicarse.'],2,'El proyecto final debe demostrar comprensión, aplicación, adaptación, límites y capacidad de reflexión.'),
    ]
  },
]

