export function getModule(moduleId: string | undefined): CourseModule | undefined {
  return curriculum.find((item) => item.id === moduleId)
}

export function getLesson(moduleId: string | undefined, lessonId: string | undefined): { module: CourseModule; lesson: Lesson; index: number } | undefined {
  const module = getModule(moduleId)
  if (!module) return undefined
  const index = module.lessons.findIndex((item) => item.id === lessonId)
  if (index < 0) return undefined
  return { module, lesson: module.lessons[index], index }
}

export const courseStats = {
  modules: curriculum.length,
  lessons: curriculum.reduce((total, item) => total + item.lessons.length, 0),
  plannedHours: curriculum.reduce((total, item) => total + item.hours, 0),
  lessonMinutes: curriculum.reduce((total, item) => total + item.lessons.reduce((minutes, lessonItem) => minutes + lessonItem.duration, 0), 0),
}
